(window.WCD=window.WCD||[]).push(["heros",[["Q1735229",1,"super","Adam Warlock","C","Adam Warlock est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, puis développé de façon significative par les scénaristes Roy Thomas et Jim Starlin, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #66 en septembre 1967.","Adam Warlock est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Adam_Warlock","c:c/ce/SDCC_2012_-_Adam_Warlock_%26_Pip_the_Troll_%287567383358%29.jpg"],["Q48833172",7,"super","Batwoman","C","Kathy Kane est un personnage de fiction créé par Bob Kane et Sheldon Moldoff dans Detective Comics #233 en 1956. Elle porte le costume de Batwoman.","Kathy Kane est un personnage de fiction créé par Bob Kane et Sheldon Moldoff dans Detective Comics #233 en 1956.","fr:Batwoman","c:3/35/Logo_Batwoman.png"],["Q575227",8,"super","Beast Boy","C","Beast Boy ou Changelin est un personnage de fiction, super-héros appartenant à l'univers de DC Comics. Il est connu principalement comme membre des Teen Titans. Créé par le scénariste Arnold Drake et l'artiste Bob Brown, il apparaît pour la première fois dans The Doom Patrol no 99.","Beast Boy ou Changelin est un personnage de fiction, super-héros appartenant à l'univers de DC Comics.","fr:Beast_Boy","c:3/32/New_York_Comic_Con_2016_-_Teen_Titans_%2830069434132%29_%28cropped%29_Beast_Boy.jpg",{"cats":["heros","persos_anim"]}],["Q599124",9,"super","Black Canary","C","Black Canary est une super-héroïne appartenant à l'univers de DC Comics. Créé par le scénariste Robert Kanigher et le dessinateur Carmine Infantino, le personnage de fiction apparaît pour la première fois dans le comic book Flash Comics #86 en août 1947.","Black Canary est une super-héroïne appartenant à l'univers de DC Comics.","fr:Black_Canary","c:2/25/Wondercon_2015-7886_%2817037777676%29.jpg"],["Q885626",11,"super","Blue Beetle","C","Blue Beetle est un super-héros qui a connu plusieurs incarnations et plusieurs éditeurs. Il a été créé par Charles Nicholas Wojtkowski et Will Eisner.","Blue Beetle est un super-héros qui a connu plusieurs incarnations et plusieurs éditeurs.","fr:Blue_Beetle","c:f/fe/Blue_Beetle.jpg"],["Q2267017",12,"super","Cable","PC","Nathan Summers, alias Cable est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #201 en janvier 1986.","Nathan Summers, alias Cable est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Cable_(comics)","c:e/ed/Cable_and_Hope_cosplays.jpg"],["Q910204",15,"super","Chose","C","Benjamin « Ben » Grimm, alias la Chose, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #1 en novembre 1961.",119,"fr:Chose_(comics)","c:5/5c/Fantastic_Four_Cosplays_%28cropped%29.jpg"],["Q60002",17,"super","Colossus","C","Piotr « Peter » Rasputin, alias Colossus, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975.",114,"fr:Colossus_(super-héros)","c:d/dd/Montreal_Comiccon_2015_-_Colossus_%2819267529469%29.jpg"],["Q5342183",22,"super","Diablo","PC","Kurt Wagner, alias Diablo est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975, en compagnie des Nouveaux X-Men.","Kurt Wagner, alias Diablo est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Diablo_(Kurt_Wagner)","c:d/de/2014_Dragon_Con_Cosplay_-_Nightcrawler_%2815123640992%29.jpg"],["Q2519257",24,"super","Dr Manhattan","PC","Le Dr Manhattan est un des personnages du comic Watchmen d'Alan Moore.",null,"fr:Dr_Manhattan","c:f/f6/Dragon_Con_2014_-_Dr_Manhattan_%2815014296223%29.jpg"],["Q898039",25,"super","Drax le Destructeur","C","Arthur Douglas, alias Drax le Destructeur est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Jim Starlin et le dessinateur Mike Friedrich, le personnage de fiction apparaît pour la première fois dans le comic book The Invincible Iron Man #55 en février 1973.",114,"fr:Drax_le_Destructeur","c:a/a1/SDCC_2015_-_Drax_the_Destroyer_%2818974525464%29.jpg"],["Q913359",26,"super","Elektra","C","Elektra Natchios, alias Elektra est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créée par Frank Miller, le personnage de fiction apparaît pour la première fois dans le comic book Daredevil #168 en janvier 1981.",114,"fr:Elektra_(comics)","c:5/52/Elektra_-_Kyllie_Cosplay_-_Renaud_D._Photography.jpg"],["Q672591",27,"super","Faucon","C","Samuel « Sam » Wilson, alias le Faucon est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Gene Colan, le personnage de fiction apparaît pour la première fois dans le comic book Captain America #117 en septembre 1969.",118,"fr:Faucon_(comics)","c:5/59/NYCC_2014_-_Falcon_%2815501191145%29.jpg"],["Q302186",28,"super","Fauve","C","Henry « Hank » McCoy, alias le Fauve est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #1 en septembre 1963.",116,"fr:Fauve_(comics)","c:2/2c/Beast_of_the_X-Men.jpg"],["Q510450",29,"super","Femme invisible","C","Jane Storm, alias l’Invisible puis la Femme invisible, aussi appelée Mme Fantastique, est une super-héroïne évoluant dans l’univers Marvel de la maison d'édition Marvel Comics.",116,"fr:Femme_invisible_(comics)","c:1/17/Cosplay_Invisible_Woman_Dracon_Con_2013.jpg"],["Q2639150",31,"super","Gambit","PC","Remy LeBeau, alias Gambit est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Jim Lee, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men Annual #14 en juillet 1990 puis dans Uncanny X-Men #266 en août 1990.","Remy LeBeau, alias Gambit est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Gambit_(comics)","c:3/38/SDCC_2012_-_Gambit_%287574607722%29.jpg"],["Q2721152",32,"super","Gamora","C","Gamora est une super-héroïne extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste et dessinateur Jim Starlin, le personnage de fiction apparaît pour la première fois dans le comic book Strange Tales #180 de 1975.","Gamora est une super-héroïne extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics.","fr:Gamora","c:9/96/Gamora_Cosplayer_at_the_2023_Comic-Con_International.jpg"],["Q868958",33,"super","Ghost Rider","R","Ghost Rider est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par les scénaristes Roy Thomas et Gary Friedrich, ainsi que le dessinateur Mike Ploog, le personnage de fiction apparaît pour la première fois sous sa forme actuelle dans le comic book Marvel Spotlight #5 en août 1972.","Ghost Rider est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics.","fr:Ghost_Rider_(comics)","c:c/cf/2018-03-18_13-03-18_ILCE-6500_DSC06818_DxO_%2841928236592%29.jpg"],["Q648125",37,"super","Guêpe","C","Janet van Dyne, alias la Guêpe est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Tales to Astonish #44 en juin 1963.",113,"fr:Guêpe_(comics)","c:6/69/Riddle_as_the_Wasp_%289333600596%29.jpg"],["Q2345627",38,"super","Hal Jordan","L","Harold « Hal » Jordan est un héros de fiction appartenant à DC Comics. La première apparition du personnage est dans Showcase #22.","Harold « Hal » Jordan est un héros de fiction appartenant à DC Comics.","fr:Hal_Jordan","c:f/f9/New_York_Comic_Con_2014_-_Hal_Jordan_cosplay_%2815344153580%29.jpg"],["Q2359610",39,"super","Hawkman","C","Hawkman est le nom de plusieurs personnages de super-héros appartenant à DC Comics. Il est systématiquement dépeint comme un guerrier réincarné à thématique de faucon, ayant accès au métal Nth fictif qui lui confère une multitude de pouvoirs, et affichant une préférence pour les armes archaïques. Il est souvent associé à sa compagne de réincarnation et amante, Hawkgirl.","Hawkman est le nom de plusieurs personnages de super-héros appartenant à DC Comics.","fr:Hawkman","https://upload.wikimedia.org/wikipedia/en/thumb/3/32/Hawkman_%28DC_Comics%29_001.png/330px-Hawkman_%28DC_Comics%29_001.png"],["Q3785909",41,"super","Hit-Girl","C","Mindy Macready, alias Hit-Girl, est un personnage fictif créé par l'écrivain Mark Millar et l'artiste John Romita, Jr. dans la série de comics Kick-Ass, publiée par Marvel Comics aux États-Unis et Panini en France. C'est une jeune fille formée au combat et à la self-défense par son père Damon McCready dès son très jeune âge pour devenir une super-héroïne. Dans le comics, ce personnage est présenté comme un personnage secondaire qui aide le protagoniste principal, Kick-Ass.","Mindy Macready, alias Hit-Girl, est un personnage fictif créé par l'écrivain Mark Millar et l'artiste John Romita, Jr.","fr:Hit-Girl_(personnage)","c:d/dd/Cosplay_of_Hit-Girl_at_AVA_Expo_2013-1.jpg"],["Q838088",43,"super","Iceberg","C","Robert « Bobby » Drake, alias Iceberg, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book X-Men #1 en septembre 1963.",118,"fr:Iceberg_(comics)","c:8/89/NYCC_2014_-_Iceman_%2815324714370%29.jpg"],["Q1194243",44,"super","Iron Fist","C","Daniel « Danny » Rand, alias Iron Fist est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Roy Thomas et le dessinateur Gil Kane, le personnage de fiction apparaît pour la première fois dans le comic book Marvel Premiere #15 en mai 1974.",118,"fr:Iron_Fist_(comics)","c:e/ec/Ironfist%2C_straight_out_of_the_comics_HDR_C2E2_2013_%288688116326%29_%28cropped%29.jpg"],["Q28006858",47,"super","James Barnes","PC","James Barnes, alias Bucky est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Joe Simon et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Captain America Comics #1 chez Timely Comics en mars 1941.","James Barnes, alias Bucky est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:James_Barnes_(comics)","c:3/3a/Wizard_World_Anaheim_2011_-_Bucky_Barnes.jpg"],["Q2271377",49,"super","Jessica Jones","PC","Jessica Jones est un personnage de fiction de l'univers Marvel créé en 2001 par Brian Michael Bendis et Michael Gaydos. C'est une ancienne super-héroïne. Elle est connue sous d'autres pseudonymes, comme Jewel ou Knightress.","Jessica Jones est un personnage de fiction de l'univers Marvel créé en 2001 par Brian Michael Bendis et Michael Gaydos.","fr:Jessica_Jones","c:c/c4/Jessica_Jones_-_24801301121.jpg"],["Q2663841",50,"super","John Constantine","PC","John Constantine est le personnage de fiction principal de la série de comics Hellblazer publiée par DC Comics. C'est un anti-héros, spécialiste de la magie noire et de l'occulte. Il se caractérise par un style sarcastique et parfois méprisant envers les autres. Sa première apparition a lieu dans le comics Swamp Thing en 1985, sous la plume d'Alan Moore.","John Constantine est le personnage de fiction principal de la série de comics Hellblazer publiée par DC Comics.","fr:John_Constantine","c:5/55/WonderCon_2014_-_Constatine_cosplay_%2813955024943%29_%28cropped%29.jpg"],["Q15208946",52,"super","Kamala Khan","C","Kamala Khan est un personnage de fiction, une super-héroïne de l'univers Marvel de la maison d'édition américaine Marvel Comics. Créé par les éditeurs Sana Amanat et Stephen Wacker, la scénariste G. Willow Wilson et le dessinateur Adrian Alphona, le personnage apparaît pour la première fois dans le comic book Captain Marvel Vol. 7 no 14 d'août 2013, et obtient son premier comics en solo en 2014, intitulé Ms. Marvel. Elle est la cinquième héroïne à prendre le nom de code de Miss Marvel.",113,"fr:Kamala_Khan","c:8/88/Dragon_Con_2015_-_Ms_Marvel_%2821904768165%29.jpg"],["Q6404178",53,"super","Kick-Ass","C","David « Dave » Lizewski, alias Kick-Ass et Nom de Code: Amérique, est le personnage éponyme de la série de comics Kick-Ass, Big Game, et Nemesis: Forever, publiée par Marvel Comics aux États-Unis et par Panini Comics en France. Ce personnage a été créé par l'écrivain Mark Millar et l'artiste John Romita, Jr..",113,"fr:Kick-Ass_(personnage)","c:8/84/Cosplay_of_Kick-Ass_at_AVA_Expo_2013.jpg"],["Q947755",54,"super","Le Fantôme","C","Le Fantôme ou Fantôme ou, occasionnellement, Le Fantôme du Bengale, est une série de bande dessinée américaine créée par Lee Falk. Elle est diffusée sous forme de comic strip depuis le 17 février 1936 pour la bande quotidienne en noir et blanc et depuis le 28 mai 1939 pour la planche dominicale en couleur.",116,"fr:Le_Fantôme_(bande_dessinée)","c:3/3a/The_Phantom%2C_Australian_Woman%27s_Mirror_2.jpg"],["Q1510225",55,"super","Le Frelon vert","C","Le Frelon vert est un justicier masqué créé en 1936 pour la radio américaine, accompagné de son fidèle chauffeur Kato, joué par Bruce Lee dans la série télé.","","en:Green_Hornet","c:5/5a/Van_Williams_as_Green_Hornet_1966_%28cropped%29.JPG"],["Q616658",56,"super","Les Indestructibles","C","Les Indestructibles, ou Les Incroyable au Québec, est le sixième film d'animation en images de synthèse réalisé par les studios Pixar, et le premier film de la saga des Indestructibles. Écrit et réalisé par Brad Bird et coproduit par Walt Disney Pictures, il est sorti sur les écrans de cinéma à Noël 2004. Quatorze ans après, une suite sort le 4 juillet 2018, par Walt Disney Pictures, suivie d'une seconde suite, prévue pour 2028.",119,"fr:M._Indestructible","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f7/Les_Indestructibles_Logo.png/330px-Les_Indestructibles_Logo.png"],["Q927354",57,"super","Les Jeunes Titans","PC","Les Jeunes Titans, aussi connus en tant que Teen Titans, The New Teen Titans, The New Titans, et The Titans, est une équipe de super-héros de comics publiée par DC Comics. Comme le nom de l’équipe le suggère, ses membres sont habituellement des adolescents. Beaucoup de ces adolescents ont été des acolytes des super-héros principaux de DC, notamment dans La ligue de justice d'Amérique. Début 2014, DC Comics annonce le lancement d'un nouveau magazine Teen Titans pour juillet 2014.",116,"fr:Les_Jeunes_Titans","https://upload.wikimedia.org/wikipedia/en/thumb/f/f4/Titans_01_2023_cover.jpg/330px-Titans_01_2023_cover.jpg"],["Q2267760",59,"super","Luke Cage","C","Luke Cage, alias Power Man est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par Archie Goodwin, George Tuska, Roy Thomas et John Romita, Sr., le personnage de fiction apparaît pour la première fois dans le comic book Luke Cage, Hero for Hire #1, en juin 1972.","Luke Cage, alias Power Man est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Luke_Cage","c:2/21/Luke_Cage_cosplay.jpg"],["Q838097",60,"super","Malicia","E","Anna Marie, alias Malicia est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Michael Golden, le personnage de fiction apparaît pour la première fois dans le comic book The Avengers Annual #10 en 1981.","Anna Marie, alias Malicia est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Malicia_(comics)","c:a/a0/Awesome_con_2016_Cosplay_of_Rogue_from_X-Men-_The_Animated_Series.jpg"],["Q59654462",61,"super","Marinette Dupain-Cheng","C","Marinette Dupain-Cheng, aussi appelée Ladybug sous sa forme de super-héroïne, est l'un des deux personnages principaux de la série d'animation Miraculous: Les Aventures de Ladybug et Chat Noir, créée par Thomas Astruc. Collégienne parisienne passionnée de mode et de création, elle se transforme en Ladybug grâce à ses boucles d'oreilles magiques, les Miraculous, et à sa kwami Tikki.",118,"fr:Marinette_Dupain-Cheng","https://upload.wikimedia.org/wikipedia/en/thumb/4/4f/Marinette_Dupain-Cheng.png/330px-Marinette_Dupain-Cheng.png"],["Q3294090",62,"super","Mark Grayson","C","Mark Grayson, alias Invincible, est le personnage principal et éponyme du comic Invincible.",null,"fr:Mark_Grayson","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Invincible_52.jpg/330px-Invincible_52.jpg"],["Q1037532",64,"super","Moon Knight","R","Marc Spector, alias Moon Knight est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par le scénariste Doug Moench et le dessinateur Don Perlin, le personnage de fiction apparaît dans le comic book Werewolf by Night #32 en août 1975, un crossover dans lequel se trouve aussi le personnage de Jack Russel.","Marc Spector, alias Moon Knight est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics.","fr:Moon_Knight","c:3/38/San_Diego_Comic-Con_2019_-_Moon_Knight.jpg"],["Q613067",66,"super","Namor","PC","Namor McKenzie, alias Namor, aussi connu comme le Prince des mers est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le dessinateur et scénariste Bill Everett, le personnage de fiction apparaît pour la première fois dans le comic book Motion Picture Funnies Weekly en avril 1939.",118,"fr:Namor","c:0/0a/Namor_%289371515878%29_cropped.jpg"],["Q686623",69,"super","Nightwing","C","Nightwing est l'identité de super-héros adoptée par Dick Grayson, le premier Robin, devenu adulte et sorti de l'ombre de Batman (DC Comics).","","en:Nightwing","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/Nightwing_Vol_4_137_%282026_Cover_B_David_Nakayama_art.png/330px-Nightwing_Vol_4_137_%282026_Cover_B_David_Nakayama_art.png"],["Q746838",71,"super","Plastic Man","C","Plastic Man est un super-héros de comics, créé par Jack Cole en août 1941, qui a fait sa première apparition dans Police Comics no 1, durant l'Âge d'or des comics.",113,"fr:Plastic_Man","c:d/df/Police_Comics_no._38_%28cover_art%29.jpg"],["Q948668",72,"super","Power Girl","C","Power Girl, de son vrai nom Kara Zor-L, également connue sous les identités civiles de Karen Starr et Paige Stetler, est une super-héroïne créée en janvier 1976 par Gerry Conway, Ric Estrada et Wally Wood pour le compte de DC Comics. Le personnage apparaît pour la première fois dans le numéro 58 du comic book All Star Comics.",116,"fr:Power_Girl","c:6/6a/Japan_Expo_2010_Power_Girl_cosplay.jpg"],["Q333156",73,"super","Power Rangers","E","Power Rangers est une franchise de médias américaine fondée sur une équipe de super-héros. Les Power Rangers sont adaptés des séries japonaises Super sentai, les producteurs américains rachetant les droits d'utilisation des images et les costumes aux producteurs japonais.","Power Rangers est une franchise de médias américaine fondée sur une équipe de super-héros.","fr:Power_Rangers","c:c/c8/Power_Rangers_Samurai.jpg",{"cats":["heros","enfance"]}],["Q838076",74,"super","Professeur Xavier","R","Le professeur Charles Xavier, alias le Professeur Xavier ou le Professeur X, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #1 en septembre 1963.",119,"fr:Professeur_Xavier","c:9/99/SDCC13_-_Professor_X.jpg"],["Q110095070",75,"super","Psylocke","C","Psylocke est une super-héroïne des X-Men (Marvel), télépathe et experte en arts martiaux, capable de créer des lames psychiques.","","en:Psylocke","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/Excalibur_%28Vol._4%29%2C_No._19_%28Textless_Variant%29.jpg/330px-Excalibur_%28Vol._4%29%2C_No._19_%28Textless_Variant%29.jpg"],["Q245928",78,"super","Raven","PC","Raven est une super-héroïne de comics appartenant à l'univers de DC Comics. Raven a été un membre important des New Teen Titans et a récemment rejoint les rangs des Teen Titans modernes. Raven est une empathe, elle peut se téléporter et peut faire sortir son âme dans un corps astral qui peut se battre physiquement.","Raven est une super-héroïne de comics appartenant à l'univers de DC Comics.","fr:Raven_(DC_Comics)","c:5/55/C2E2_2014_-_Raven_%2814085544008%29.jpg",{"cats":["heros","persos_anim"]}],["Q638476",80,"super","Rocket Raccoon","C","Rocket Raccoon est un super-héros extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics.",null,"fr:Rocket_Raccoon","c:e/e5/Cosplay_de_Rocket_Raccoon_%28marvel%29.jpg"],["Q2346769",81,"super","Rorschach","PC","Rorschach est un personnage de fiction et antihéros de la série de comic book Watchmen. Créé par Alan Moore et Dave Gibbons, il apparaît pour la première fois dans Watchmen #1 en 1986.","Rorschach est un personnage de fiction et antihéros de la série de comic book Watchmen.","fr:Rorschach_(comics)","c:5/51/RorschachCloseUp.jpg"],["Q2262357",82,"super","Shang-Chi","C","Shang-Chi, aussi appelé le Maître du kung-fu est un super-héros évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Steve Englehart, le dessinateur Jim Starlin et l'encreur Al Milgrom, le personnage de fiction apparaît pour la première fois dans le comic book Special Marvel Edition #15 en décembre 1973.",117,"fr:Shang-Chi","https://upload.wikimedia.org/wikipedia/en/thumb/6/62/Shang-Chi_Vol_1_%2C1.jpg/330px-Shang-Chi_Vol_1_%2C1.jpg"],["Q929285",84,"super","Sorcière rouge","E","Wanda Maximoff, alias la Sorcière rouge, est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book X-Men #4 en mars 1964.",116,"fr:Sorcière_rouge","c:f/f7/Brasil_Comic_Con_2014_%2815178816243%29.jpg"],["Q18754957",86,"super","Spider-Gwen","C","Spider-Gwen (Ghost-Spider) est une version alternative de Gwen Stacy (Marvel), qui a été mordue par l'araignée à la place de Peter Parker.","","en:Spider-Gwen","https://upload.wikimedia.org/wikipedia/en/thumb/4/42/Spider-Gwen_Vol_1_1.jpg/330px-Spider-Gwen_Vol_1_1.jpg"],["Q59826",88,"super","Spider-Man (Miles Morales)","R","Miles Morales, alias Spider-Man né le 21 juillet 2005 à Brooklyn, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Brian Michael Bendis et la dessinatrice Sara Pichelli, ce personnage de fiction apparait pour la première fois dans le comic book Ultimate Comics: Fallout #4 en août 2011.",118,"fr:Spider-Man_(Miles_Morales)","c:3/3a/Miles_Morales_cosplay_at_Asia_Comic_Expo_001_2.jpg"],["Q4353353",89,"super","Squirrel Girl","C","Doreen Green, alias Squirrel Girl, est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par l'auteur Will Murray et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Marvel Super-Heroes #8 en janvier 1992.",117,"fr:Squirrel_Girl","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Marvel_Logo.svg/330px-Marvel_Logo.svg.png"],["Q427987",91,"super","Starfire","PC","Starfire est le nom de plusieurs héros et personnages. Toutefois, c'est Koriand'r qui est officiellement Starfire, créé en 1980 par Mark Wolfman et George Pérez dans DC Comics Presents no 26.","Starfire est le nom de plusieurs héros et personnages.","fr:Starfire","c:2/22/WonderCon_2012_-_Starfire_from_Teen_Titans_%287019136731%29.jpg"],["Q4354752",92,"super","Static","C","Static est un super-héros de DC Comics créé en 1993, un adolescent capable de contrôler l'électricité. Il a eu sa propre série animée, Static Choc.","","en:Static_(DC_Comics)","https://upload.wikimedia.org/wikipedia/en/thumb/d/de/Static_%28Virgil_Hawkins%29.png/330px-Static_%28Virgil_Hawkins%29.png"],["Q1427625",96,"super","Swamp Thing","PC","La Créature du marais ou La Créature des marais est le personnage principal de la série de bande dessinée américaine du même nom créée dans les années 1970 par Len Wein et Berni Wrightson.",119,"fr:Swamp_Thing","c:a/a3/Swamp_Thing_and_Len_Wein.jpg"],["Q584585",98,"super","Torche humaine","C","Jonathan « Johnny » Storm, alias la Torche humaine est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #1 en novembre 1961.",113,"fr:Torche_humaine","c:3/3b/Dragon_Con_2013_-_Human_Torch_%289694709273%29.jpg"],["Q632212",99,"super","Tornade","PC","Ororo Munroe, alias Tornade est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975.","Ororo Munroe, alias Tornade est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Tornade_(comics)","c:0/09/Anime_Expo_2011_-_Storm_close-up_%285892747839%29.jpg"],["Q1381762",100,"super","Tortues Ninja","E","Les Tortues Ninja sont des personnages de fiction créés par Kevin Eastman et Peter Laird en 1984 dans le comics du même nom.",119,"fr:Tortues_Ninja","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b6/Tortues_Ninja.png/330px-Tortues_Ninja.png"],["Q860922",106,"super","Zatanna","C","Zatanna Zatara est un personnage de fiction appartenant à l'univers de DC Comics. Créé par le scénariste Gardner Fox et le dessinateur Murphy Anderson, elle apparaît pour la première fois dans le comic book Hawkman vol. 1 #4 en 1964. Zatanna est la fille d'un grand magicien qui a, dans le passé, appris à Bruce Wayne nombre de ses tours. Zatanna et Bruce ont eu une brève histoire d'amour avant qu'elle ne doive partir pour suivre son père et que Bruce ne devienne Batman.","Zatanna Zatara est un personnage de fiction appartenant à l'univers de DC Comics.","fr:Zatanna","c:f/f5/San_Diego_Comic-Con_2019_-_Zatanna.jpg"],["Q2085488",107,"mechant","Agent Smith","C","L'Agent Smith est un personnage de fiction apparaissant dans la série de films Matrix et joué par l'acteur Hugo Weaving dans Matrix, Matrix Reloaded et Matrix Revolutions, puis par Jonathan Groff et Yahya Abdul-Mateen II dans Matrix Resurrections. Il est un agent, c'est-à-dire un programme qui parcourt la Matrice pour en assurer la sécurité et lutter contre les humains qui la piratent.",119,"fr:Agent_Smith","c:b/bf/Warner_Brothers_VIP_studio_tour_-_Matrix_mannequins_%282862323128%29.jpg"],["Q1146291",108,"mechant","Albert Wesker","E","Albert Wesker est un personnage de fiction et l'un des principaux antagonistes de la série de jeux vidéo Resident Evil créé par Capcom.",118,"fr:Albert_Wesker","",{"cats":["heros","horreur","persos_jv"]}],["Q1628095",111,"mechant","Annie Wilkes","C","Annie Wilkes est l'infirmière psychopathe du roman Misery de Stephen King (1987), qui séquestre son écrivain préféré. Kathy Bates a remporté l'Oscar pour ce rôle.","","en:Annie_Wilkes","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/KathyWilkins1212.jpg/330px-KathyWilkins1212.jpg",{"cats":["heros","horreur"]}],["Q4775712",112,"mechant","Anton Chigurh","R","Anton Chigurh est le tueur implacable de No Country for Old Men (Cormac McCarthy), armé d'un pistolet d'abattage. Javier Bardem a remporté l'Oscar pour ce rôle.","","en:Anton_Chigurh","https://upload.wikimedia.org/wikipedia/en/thumb/4/41/Anton_Chigurh.jpg/330px-Anton_Chigurh.jpg"],["Q2071805",113,"mechant","Apocalypse","R","En Sabah Nur, alias Apocalypse est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par la scénariste Louise Simonson et le dessinateur Jackson Guice, le personnage de fiction apparaît pour la première fois dans le comic book X-Factor #5 en juin 1986.","En Sabah Nur, alias Apocalypse est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Apocalypse_(comics)","c:c/cf/San_Diego_Comic_Con_2014-1323_%2814571754679%29.jpg"],["Q924817",114,"mechant","Auric Goldfinger","C","Auric Goldfinger est un ennemi de James Bond, méchant principal du roman et du film Goldfinger.",null,"fr:Auric_Goldfinger","https://upload.wikimedia.org/wikipedia/en/thumb/4/47/Goldfinger_by_Gert_Fr%C3%B6be.jpg/330px-Goldfinger_by_Gert_Fr%C3%B6be.jpg"],["Q2537674",117,"mechant","Biff Tannen","C","Biff Tannen est un personnage de fiction créé par Robert Zemeckis et Bob Gale et interprété par Thomas F. Wilson dans la trilogie Retour vers le futur.","Biff Tannen est un personnage de fiction créé par Robert Zemeckis et Bob Gale et interprété par Thomas F.","fr:Biff_Tannen","https://upload.wikimedia.org/wikipedia/en/thumb/1/15/BiffTannenBackToTheFuture1985.jpg/330px-BiffTannenBackToTheFuture1985.jpg"],["Q391161",118,"mechant","Black Adam","C","Black Adam est un personnage fictif de DC Comics créé en 1945 par Otto Binder et C. C. Beck comme une version maléfique du super-héros Shazam. Sa personnalité a évolué au fil des années et aujourd'hui, elle oscille entre le bien et le mal.","Black Adam est un personnage fictif de DC Comics créé en 1945 par Otto Binder et C.","fr:Black_Adam","c:f/fa/Logo_Black_Adam.png"],["Q2538991",119,"mechant","Black Manta","C","Black Manta est un personnage de fiction, un super-vilain de DC Comics créé par Bob Haney & Nick Cardy dans Aquaman #35 en septembre 1967. C'est l'ennemi juré du super-héros Aquaman.",119,"fr:Black_Manta","https://upload.wikimedia.org/wikipedia/en/thumb/5/5f/Black_Manta_Aquaman.webp/330px-Black_Manta_Aquaman.webp"],["Q51790",120,"mechant","Boba Fett","C","Boba Fett est un personnage de la saga cinématographique Star Wars.",null,"fr:Boba_Fett","c:3/38/Boba_Fett_-_A_Fett_to_Remember.jpg"],["Q735721",121,"mechant","Bouffon vert","C","Le Bouffon vert ou le Gobelin vert au Québec est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #14 en juillet 1964.",118,"fr:Bouffon_vert","c:c/c2/Greengoblincosplayercopiz.jpg"],["Q592909",122,"mechant","Brainiac","PC","Brainiac est un personnage de fiction de DC Comics et un ennemi de Superman, créé par Otto Binder & Al Plastino dans Action Comics #242 en juillet 1958.",116,"fr:Brainiac_(comics)","c:5/51/New_York_Comic_Con_2015_-_Brainiac_%2821442078224%29.jpg"],["Q1753328",123,"mechant","Carnage","C","Cletus Kasady, alias Carnage, est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste David Michelinie et le dessinateur Mark Bagley, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #361 en avril 1992.","Cletus Kasady, alias Carnage, est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Carnage_(comics)","c:7/7e/Wondercon_2016_-_Carnage_Cosplay_%2825808079300%29.jpg"],["Q6569036",126,"mechant","Personnages d'Hercule","C","Les personnages d'Hercule (Disney, 1997) réunissent le héros Hercule, Mégara, le satyre Philoctète, le cheval ailé Pégase et le dieu des Enfers Hadès.","","en:List_of_Disney's_Hercules_characters","https://upload.wikimedia.org/wikipedia/en/thumb/7/76/Disney%27s_Hercules_characters.jpg/330px-Disney%27s_Hercules_characters.jpg"],["Q2620997",127,"mechant","Cheetah","C","Cheetah est un personnage de fiction créé par William Moulton Marston. Il est apparu dans plusieurs œuvres liés à l'univers de DC Comics. Il s'agit de la pire ennemie de Wonder Woman.","Cheetah est un personnage de fiction créé par William Moulton Marston.","fr:Cheetah_(DC_Comics)","c:5/51/Long_Beach_Comic_Expo_2011_-_Cheetah_%285648076127%29.jpg"],["Q520812",128,"mechant","Claude Frollo","C","Claude Frollo est un des personnages centraux du roman Notre-Dame de Paris de Victor Hugo.",null,"fr:Claude_Frollo","c:3/3a/Gustave_Brion_-_Claude_Frollo.jpg"],["Q51727",129,"mechant","Comte Dooku","C","Le comte Dooku, alias Dark Tyranus, ou Darth Tyranus, est un personnage de fiction de la saga Star Wars. Membre de la maison Serenno qui dirige la planète du même nom, il est abandonné par sa famille, effrayée par sa sensibilité à la Force, et recueilli par l'ordre Jedi. Il devient au cours de sa formation le padawan de Yoda puis, une fois devenu chevalier, forme Qui-Gon Jinn.","Le comte Dooku, alias Dark Tyranus, ou Darth Tyranus, est un personnage de fiction de la saga Star Wars.","fr:Comte_Dooku","c:d/d8/Dooku.jpg"],["Q51766",131,"mechant","Dark Maul","PC","Dark Maul, ou plus simplement Maul, Darth Maul dans la version originale en anglais et la traduction québécoise, est un personnage de fiction de l'univers de Star Wars qui apparaît dans l'épisode I, dans la série Star Wars: The Clone Wars aux côtés de son frère, Savage Opress, dans la série Star Wars Rebels, Solo: A Star Wars Story, et enfin dans Maul: Seigneur de l'ombre. C'est un Zabrak originaire de la planète Dathomir. Ce personnage a été créé par l'illustrateur Iain Mccaig pour Industrial Light & Magic.",119,"fr:Dark_Maul","c:8/86/Darth_Maul_Cosplayer_at_MCM_Comic_Con_October_2016.jpg"],["Q1181328",133,"mechant","Deathstroke","PC","Deathstroke de son vrai nom Slade Wilson est un personnage de l'univers de DC Comics. Il s'agit d'un mercenaire-assassin, essentiellement connu comme un ennemi des Teen Titans, et plus particulièrement, dans la série animée, de leur leader Robin. Mais il est aussi un anti-héros, qui a eu le droit en certaines occasions à sa propre série. On l'appelle l'Assassin Romain.","Deathstroke de son vrai nom Slade Wilson est un personnage de l'univers de DC Comics.","fr:Deathstroke","c:1/1c/C2E2_2014_-_Deathstroke_%2814268417541%29.jpg"],["Q431862",134,"mechant","Dents-de-sabre","PC","Victor Creed, alias Dents-de-sabre est un super-vilain évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur John Byrne, le personnage de fiction apparaît pour la première fois dans le comic book Iron Fist #14 en août 1977.",115,"fr:Dents-de-sabre","c:e/ef/SDCC_2012_-_Sabretooth_%287573786874%29.jpg"],["Q716941",137,"mechant","Dolores Ombrage","PC","Dolores Jane Ombrage est un personnage fictif issu de la saga Harry Potter. Elle est une sous-secrétaire d'État auprès du ministre de la Magie, Cornelius Fudge. Issue de la bureaucratie du ministère de la Magie, c'est une femme malsaine, bornée et particulièrement perverse, hypocrite. Elle est prête à tous les moyens, pour imposer sa loi à l'école de sorcellerie Poudlard et ainsi obliger Harry Potter à ne plus annoncer au monde des sorciers le retour de Voldemort.","Dolores Jane Ombrage est un personnage fictif issu de la saga Harry Potter.","fr:Dolores_Ombrage","c:4/4e/Dolores_Ombrage.jpg"],["Q126680",138,"mechant","Doomsday","PC","Doomsday est un super-vilain appartenant à l'univers de DC Comics. Il est apparu pour la première fois dans Superman: The Man of Steel #17 en novembre 1992. C'est un ennemi de Superman, il est connu pour l'avoir tué dans Superman #75: La Mort de Superman publié en janvier 1993, et plus récemment dans le long-métrage Batman V Superman: L'Aube de la Justice.","Doomsday est un super-vilain appartenant à l'univers de DC Comics.","fr:Doomsday_(DC_Comics)","c:d/d4/NYCC_2018_-_Doomsday_Cosplayer.jpg"],["Q2066394",139,"mechant","Dormammu","C","Dormammu est un super-vilain et une entité interdimensionnelle évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Strange Tales #126 en novembre 1964.",116,"fr:Dormammu","https://upload.wikimedia.org/wikipedia/en/thumb/8/80/Dormammu.png/330px-Dormammu.png"],["Q3266236",141,"mechant","Dracula","E","Le comte Dracula est un personnage de fiction créé par l'écrivain Bram Stoker dans son roman épistolaire Dracula publié le 26 mai 1897.",119,"fr:Dracula_(personnage)","c:9/90/Bela_Lugosi_as_Dracula%2C_anonymous_photograph_from_1931%2C_Universal_Studios.jpg",{"cats":["heros","horreur"]}],["Q2297886",142,"mechant","Electro","C","Maxwell « Max » Dillon, alias Electro est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #9 en février 1964.",118,"fr:Electro_(comics)","c:6/6e/2014_Dragon_Con_Cosplay_-_Electro_%2814937271268%29.jpg"],["Q1104987",143,"mechant","Ernst Stavro Blofeld","R","Ernst Stavro Blofeld est un personnage fictif dans la série de romans James Bond, écrits par Ian Fleming. Blofeld est le chef du SPECTRE, redoutable organisation criminelle dont le siège se trouve originellement à Paris.","Ernst Stavro Blofeld est un personnage fictif dans la série de romans James Bond, écrits par Ian Fleming.","fr:Ernst_Stavro_Blofeld","c:1/11/ChristophWaltz82AAMar10.jpg"],["Q1162210",144,"mechant","Fantômas","C","Fantômas est un personnage de fiction français créé en 1911 par Pierre Souvestre et Marcel Allain. Sévissant dans la France de la Belle Époque, ce criminel est l'archétype du génie du mal, insaisissable et mystérieux. Défiant les forces de l'ordre, et en particulier le commissaire Juve et le journaliste Jérôme Fandor, Fantômas poursuit ses activités criminelles grâce à son art du déguisement et de l'évasion.","Fantômas est un personnage de fiction français créé en 1911 par Pierre Souvestre et Marcel Allain.","fr:Fantômas","c:1/10/Fantomas_1911.jpg"],["Q841372",145,"mechant","Fléau","PC","Cain Marko, alias le Fléau est un personnage de fiction, au départ un super-vilain, évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, il apparaît pour la première fois dans le comic book X-Men #12 en juillet 1965.",117,"fr:Fléau_(comics)","c:0/00/Cosplay_Juggernaut_2012.jpg"],["Q2269136",148,"mechant","Gaston","C","Gaston est un personnage de fiction et principal antagoniste du long métrage d'animation La Belle et la Bête, des studios Disney par Gary Trousdale et Kirk Wise, sorti en 1991.",113,"fr:Gaston_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a7/Gaston%28BeautyandtheBeast%29.png/330px-Gaston%28BeautyandtheBeast%29.png"],["Q605125",149,"mechant","GLaDOS","PC","GLaDOS est un personnage fictif qui apparaît dans les jeux vidéo Portal et Portal 2. Elle a été créée par Erik Wolpaw et Kim Swift. Ellen McLain la double en version originale; Scarlett Perdereau en version française.","GLaDOS est un personnage fictif qui apparaît dans les jeux vidéo Portal et Portal 2.","fr:GLaDOS","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Glados.png/330px-Glados.png",{"cats":["heros","persos_jv"]}],["Q719748",151,"mechant","Grinch","C","Le Grinch est une créature verte et grincheuse imaginée par le Dr Seuss en 1957, qui déteste Noël et décide de le voler aux habitants de Chouville.","","en:Grinch","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/The_Grinch.png/330px-The_Grinch.png"],["Q2260732",152,"mechant","Général Zod","C","Le Général Zod est un personnage de fiction de comics appartenant à l'univers DC. Il s'agit d'un ennemi de Superman. Créé par Robert Bernstein et George Papp, il est apparu dans Adventure Comics #283 en avril 1961.","Le Général Zod est un personnage de fiction de comics appartenant à l'univers DC.","fr:Général_Zod","c:b/b1/New_York_Comic_Con_2014_-_General_Zod_%2815519505971%29.jpg"],["Q833933",153,"mechant","HAL 9000","PC","HAL 9000 est un personnage de fiction, un supercalculateur doté d'intelligence artificielle. Il a été conçu pour gérer de manière autonome les fonctions vitales du vaisseau spatial Discovery One, en mission dans l'espace vers la planète Jupiter.","HAL 9000 est un personnage de fiction, un supercalculateur doté d'intelligence artificielle.","fr:HAL_9000","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/HAL9000.svg/330px-HAL9000.svg.png"],["Q18545687",155,"mechant","Hans Gruber","C","Hans Gruber est le méchant du film Piège de cristal (1988), un voleur élégant qui prend en otage une tour de Los Angeles. Il est incarné par Alan Rickman.","","en:Hans_Gruber","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/HansGruber.jpeg/330px-HansGruber.jpeg"],["Q3043221",157,"mechant","Hela","C","Hela est une divinité et une super-vilaine évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Journey into Mystery #102 en mars 1964.","Hela est une divinité et une super-vilaine évoluant dans l’univers Marvel de la maison d'édition Marvel Comics.","fr:Hela_(Marvel_Comics)","c:9/90/Hela_%283953996709%29.jpg"],["Q1049890",158,"mechant","Homme-sable","C","William Baker, alias l'Homme-sable est un super-vilain évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #4 en septembre 1963.",115,"fr:Homme-sable","c:3/35/NYCC_2016_-_Sandman_%2829954188370%29.jpg"],["Q7070198",159,"mechant","Infirmière Ratched","PC","L'infirmière Ratched, également connue sous le nom de Mildred Ratched au cinéma et à la télévision et surnommée Big Nurse en version originale, est un personnage de fiction créé par Ken Kesey dans le roman Vol au-dessus d'un nid de coucou en 1962.",115,"fr:Infirmière_Ratched","c:8/89/Louise_Fletcher_1959_crop.jpg"],["Q366957",161,"mechant","Jason Voorhees","M","Jason Voorhees est un personnage fictif né avec une tête hydrocéphale adapté au cinéma par Victor Miller, Ron Kurz, Sean S. Cunningham et Tom Savini dans le film Vendredi 13 réalisé par Sean S. Cunningham en 1980. Il est le fils d'une cuisinière du camp Crystal Lake et devenu meurtrier. Jason Voorhees a également été représenté dans de nombreux romans, bandes dessinées, et un crossover avec un autre personnage des films d'horreur, Freddy Krueger.",115,"fr:Jason_Voorhees","c:2/2c/Jason_-_Zombie_Walk_2014_-_16112014_%2815683501399%29.jpg",{"cats":["heros","horreur"]}],["Q1985548",162,"mechant","Jigsaw","PC","John Kramer, ou Jigsaw, est un personnage de fiction, à la fois personnage central et principal antagoniste de la série de films d'horreur Saw créée par James Wan et Leigh Whannell.",119,"fr:Jigsaw_(personnage)","c:9/9e/Bell%2C_Tobin_%282007%29.jpg",{"cats":["heros","horreur"]}],["Q2053078",164,"mechant","Julius No","C","Le Docteur Julius No est un personnage de la série James Bond, que celui-ci affronte dans le roman de 1958 Docteur No et son adaptation cinématographique de 1962, James Bond 007 contre Dr No, le premier film issu d'un roman d'Ian Fleming.",117,"fr:Julius_No","https://upload.wikimedia.org/wikipedia/en/thumb/6/6c/DrJuliusNo.jpg/330px-DrJuliusNo.jpg"],["Q1982051",165,"mechant","Kang le conquérant","R","Nathaniel Richards, alias Kang le conquérant est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #19 en octobre 1963.",118,"fr:Kang_le_conquérant","c:4/44/Dragon_Con_2013_-_Kang_the_Conqueror_%289697497164%29.jpg"],["Q974336",166,"mechant","Killer Croc","C","Killer Croc est un personnage de fiction, super-vilain de l'univers de DC Comics. Créé par Gerry Conway et Don Newton, il apparaît pour la première fois dans le comic Detective Comics #523 en 1983. Sa véritable identité est Waylon Jones, un homme atteint d'une maladie de peau qui recouvre son corps d'écailles. Par la suite, sa physionomie évolue pour s'approcher de celle d'un crocodile anthropomorphe de grande taille.","Killer Croc est un personnage de fiction, super-vilain de l'univers de DC Comics.","fr:Killer_Croc","c:f/f3/Killer_Croc_%28Cosplay_March_29_2014%29.jpg"],["Q654588",167,"mechant","Kraven le chasseur","R","Serguei Kravinoff, alias Kraven le chasseur est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #15 en août 1964.",117,"fr:Kraven_le_chasseur_(Serguei_Kravinoff)","c:3/3b/SDCC_-_Kraven_the_Hunter_Cosplay_%2835308456084%29.jpg"],["Q21515016",168,"mechant","Kylo Ren","PC","Ben Solo, alias Kylo Ren, est un personnage de fiction de l'univers de Star Wars, apparu pour la première fois dans le film Le Réveil de la Force, premier épisode de la troisième trilogie. Il y fait office de principal antagoniste en tant que leader des Chevaliers de Ren, puis Suprême leader du Premier Ordre, statut qui fait de lui le successeur de Dark Vador, méchant emblématique de la trilogie originale — qui n'est autre que son grand-père.",118,"fr:Kylo_Ren","c:f/f2/Cosplay_of_Kylo_Ren_at_Japan_Expo_2023_%2853056183168%29.jpg"],["Q104880994",169,"mechant","Le Protecteur","R","John Gillman, alias Le Protecteur, est le principal antagoniste de la série de bandes dessinées The Boys ainsi que de la franchise associée, créée par Garth Ennis et Darick Robertson. Chef des « Sept », un groupe de super-héros corrompus et hédonistes financés par Vought International, le Protecteur est un personnage narcissique, égoïste et sadique qui se masque sous une image publique de héros noble et altruiste.",117,"fr:Le_Protecteur_(comics)","c:d/da/Homelander_in_Mortal_Kombat_1.png"],["Q1647348",170,"mechant","Leatherface","E","Leatherface est un personnage de fiction créé par Tobe Hooper et Kim Henkel dans le film Massacre à la tronçonneuse en 1974.",118,"fr:Leatherface","c:b/bf/Leatherface_1974.jpg",{"cats":["heros","horreur"]}],["Q19382",173,"mechant","Lézard","C","Curtis « Curt » Connors, alias le Lézard est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #6 en novembre 1963.",114,"fr:Lézard_(comics)","c:c/cb/SDCC_2012_cosplay_%287574223270%29.jpg"],["Q31378",174,"mechant","M. Bison","L","M. Bison, surnommé Dictator en tournoi et Vega au Japon, est l'un des personnages et antagonistes principaux issus de la franchise Street Fighter, éditée par Capcom. Boss final des opus 2, alpha 3 et 5, il exploite à mauvais escient les pouvoirs extraordinaires de télékinésie dont il est doté.","M.","fr:M._Bison","c:5/5e/Wondercon_2016_-_M._Bison_Cosplay_%2826014569031%29.jpg"],["Q2021531",177,"mechant","Monstre de Frankenstein","R","Le Monstre de Frankenstein ou la créature de Frankenstein est un personnage de fiction qui apparaît pour la première fois en 1818 dans le roman de Mary Shelley Frankenstein ou le Prométhée moderne. Il s'agit d'un être artificiel créé par le savant Victor Frankenstein à l'aide d'un assemblage de cadavres ramené ensuite à la vie.",116,"fr:Monstre_de_Frankenstein","c:a/a7/Frankenstein%27s_monster_%28Boris_Karloff%29.jpg",{"cats":["heros","horreur"]}],["Q18152783",178,"mechant","Mère Gothel","C","Mère Gothel est la méchante de Raiponce (Disney, 2010), qui enlève la princesse pour profiter du pouvoir de jouvence de ses cheveux magiques.","","en:Mother_Gothel","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Gothel.png/330px-Gothel.png"],["Q737236",180,"mechant","Mystique","PC","Raven Darkhölme, alias Mystique, est une super-vilaine évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Jim Mooney, le personnage de fiction apparaît pour la première fois dans le comic book Ms. Marvel #17 en juin 1978.",115,"fr:Mystique_(comics)","c:f/f3/Brasil_Game_Show_2016_%2829381528591%29.jpg"],["Q2283843",181,"mechant","Mystério","C","Mystério est le nom de plusieurs super-vilains successifs évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #13 en juin 1964.",118,"fr:Mystério","c:e/e3/New_York_Comic_Con_2013_-_Mysterio_%2810275729573%29.jpg"],["Q828473",182,"mechant","Mégatron","C","Megatron est le chef des Decepticons, les principaux antagonistes de la franchise Transformers.",null,"fr:Mégatron","c:e/e4/Cosplay_of_Megatron_at_Animagic_2007.jpg",{"cats":["heros","persos_anim"]}],["Q3352056",184,"mechant","Omni-Man","C","Omni-Man est un personnage du comic Invincible. Il est 93e du classement IGN des Super-vilains.","Omni-Man est un personnage du comic Invincible.","fr:Omni-Man","c:e/eb/Omni-Man_in_Mortal_Kombat_1.png"],["Q51770",185,"mechant","Palpatine","R","Sheev Palpatine, alias Dark Sidious, ou Darth Sidious dans les versions originale et québécoise, est un personnage de fiction, seigneur noir des Sith, homme politique et antagoniste principal de la saga Star Wars créée par George Lucas. D'abord sénateur de Naboo, Palpatine réussit à se faire élire Chancelier suprême de la galaxie, avant de fomenter un auto-coup d'État qui lui permet de devenir Empereur de l'Empire galactique pendant vingt-cinq ans.",117,"fr:Palpatine","c:6/61/MCM_2013_-_Emperor_Palpatine_%288979536884%29.jpg"],["Q203927",186,"mechant","Patrick Bateman","PC","Patrick Bateman est le personnage principal et le narrateur du roman American Psycho de Bret Easton Ellis.",null,"fr:Patrick_Bateman","c:1/1e/ChristianBaleJun09.jpg"],["Q2518973",188,"mechant","Pinhead","L","Pinhead est un personnage de fiction créé par Clive Barker dans le roman Hellraiser en 1986. Il est l'une des plus grandes icônes du cinéma d'horreur.","Pinhead est un personnage de fiction créé par Clive Barker dans le roman Hellraiser en 1986.","fr:Pinhead","c:4/43/Special_Edition_NYC_2015_-_Pinhead_%2818519207906%29.jpg",{"cats":["heros","horreur"]}],["Q844794",190,"mechant","Predator","C","Les Predators ou Prédateurs au Québec, également appelés Yautja dans des romans, constituent une espèce extraterrestre fictive caractérisée par la pratique rituelle de la chasse aux trophées d'autres formes de vie. Initialement imaginée par les scénaristes Jim et John Thomas et conçue par l'artiste d'effets spéciaux Stan Winston, l'espèce fait sa première apparition en tant qu'antagoniste dans le film de science-fiction et d'action Predator de 1987, réalisé par John McTiernan.",118,"fr:Predator_(créature)","c:3/35/The_Predator.jpg"],["Q283111",191,"mechant","Professeur Moriarty","PC","Le professeur James Moriarty est un personnage de fiction, connu pour être le plus redoutable ennemi de Sherlock Holmes. Considéré comme l'un des premiers génies du mal de la littérature, Moriarty est un cerveau criminel que Holmes décrit comme le « Napoléon du crime ».","Le professeur James Moriarty est un personnage de fiction, connu pour être le plus redoutable ennemi de Sherlock Holmes.","fr:Professeur_Moriarty","c:5/50/Moriarty_-_Sidney_Paget.jpg"],["Q1085009",192,"mechant","Pyramid Head","R","Pyramid Head est un monstre emblématique de la série de jeux d'horreur Silent Hill, reconnaissable à son énorme casque triangulaire et à son grand couteau.","","en:Pyramid_Head","https://upload.wikimedia.org/wikipedia/en/thumb/4/4c/Pyramid_Head.jpg/330px-Pyramid_Head.jpg",{"cats":["heros","horreur","persos_jv"]}],["Q252044",194,"mechant","Reine-sorcière","C","La Reine-sorcière est un personnage de fiction, principal antagoniste du long métrage d'animation Blanche-Neige et les Sept Nains, adapté du conte éponyme des frères Grimm paru en 1812.",118,"fr:Reine-sorcière","c:6/6a/Evil_Queen_in_Disney_trailer.png"],["Q2361723",195,"mechant","Requin","C","Requin est un personnage fictif des romans, films et jeux vidéo de James Bond et un ennemi récurrent de ce dernier. Incarné au cinéma par l'acteur américain Richard Kiel, il apparaît notamment dans les films L'Espion qui m'aimait et Moonraker, ainsi que dans le jeu vidéo Quitte ou double.","Requin est un personnage fictif des romans, films et jeux vidéo de James Bond et un ennemi récurrent de ce dernier.","fr:Requin_(James_Bond)","c:8/8a/Eegah-RichardKiel2.jpg"],["Q2354107",196,"mechant","Reverse-Flash","C","Reverse-Flash est l'ennemi juré de Flash chez DC Comics : un speedster maléfique venu du futur, souvent incarné par Eobard Thawne.","","en:Reverse-Flash",""],["Q572626",197,"mechant","Rhino","C","Aleksei Sytsevich, alias le Rhino est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur John Romita, Sr., le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #41 en octobre 1966.",114,"fr:Rhino_(comics)","c:d/dd/Rhino_cosplay_marvel.jpg"],["Q2596301",198,"mechant","Sadako Yamamura","PC","Sadako Yamamura est un personnage de fiction issu du roman Ring de l'écrivain japonais Kōji Suzuki. Elle apparaît également dans les adaptations cinématographiques du roman, ainsi que dans les adaptations en manga, anime, dramas, et a inspiré ses équivalents dans les remakes américains et coréens du film.","Sadako Yamamura est un personnage de fiction issu du roman Ring de l'écrivain japonais Kōji Suzuki.","fr:Sadako_Yamamura","https://upload.wikimedia.org/wikipedia/en/thumb/a/ad/Sadako_Yamamura_in_Ringu.png/330px-Sadako_Yamamura_in_Ringu.png",{"cats":["heros","horreur"]}],["Q660267",201,"mechant","Sephiroth","R","Le mot Sephiroth est le pluriel de Sefira; il désigne une puissance créatrice censée émaner d'une énergie universelle. Les Sephiroth forment un « Arbre de Vie » dont la connaissance doit, dans l'idéal, concourir à rendre la vie humaine, spirituelle et matérielle, moins chaotique, plus harmonieuse.","Le mot Sephiroth est le pluriel de Sefira; il désigne une puissance créatrice censée émaner d'une énergie universelle.","fr:Sephiroth_(Kabbale)","c:d/d5/Ktreewnames.png",{"cats":["heros","persos_jv"]}],["Q1654161",202,"mechant","Shao Kahn","C","Shao Kahn est un personnage fictif de jeu vidéo dans la série des jeux de combat Mortal Kombat.",null,"fr:Shao_Kahn","https://upload.wikimedia.org/wikipedia/en/thumb/b/b2/Shao_Kahn_2011.png/330px-Shao_Kahn_2011.png"],["Q2305638",203,"mechant","Shere Khan","C","Shere Khan est un tigre fictif, personnage du roman Le Livre de la jungle de Rudyard Kipling, ainsi que du long métrage d'animation de Walt Disney. Shere Khan est un tigre du Bengale dont le nom veut dire « seigneur tigre » en hindi/ourdou. Il est le pire ennemi de Mowgli, le héros de l'histoire.",119,"fr:Shere_Khan","c:3/38/Becque_-_Livre_de_la_jungle%2C_p35.jpeg"],["Q252662",204,"mechant","Shredder","C","Shredder, de son vrai nom Oroku Saki, est un personnage de la bande dessinée américaine des Tortues Ninja. Il s'agit aussi du chef de l'organisation connu comme le Clan des Foot. Il est l'ennemi le plus acharné des Tortues Ninja et est inlassablement repris comme tel dans toutes les incarnations de la bande dessinée depuis ses débuts.","Shredder, de son vrai nom Oroku Saki, est un personnage de la bande dessinée américaine des Tortues Ninja.","fr:Shredder","c:2/2b/San_Diego_Comic-Con_2019_-_Shredder.jpg",{"cats":["heros","persos_anim"]}],["Q2279525",205,"mechant","Sinestro","E","Sinestro est un super-vilain et un extra-terrestre originaire de Korugar appartenant à l'univers de fiction de DC Comics. Il est apparu pour la première fois dans Green Lantern Vol. 2 #7, créé par John Broome & Gil Kane.",113,"fr:Sinestro","c:6/61/WonderCon_2014_-_Sinestro_Cosplay_%2813954947165%29.jpg"],["Q127111",206,"mechant","Skeletor","C","Skeletor est un personnage fictif du dessin animé Les Maîtres de l'univers.",null,"fr:Skeletor","c:c/c0/NYCC_2018_Cosplay_of_Skeletor.jpg",{"cats":["heros","persos_anim"]}],["Q3973228",209,"mechant","Steppenwolf","C","Steppenwolf est un personnage de fiction et un super-vilain appartenant à l'univers DC. Il est créé par Jack Kirby et fait sa première apparition dans New Gods vol. 1 #7.","Steppenwolf est un personnage de fiction et un super-vilain appartenant à l'univers DC.","fr:Steppenwolf_(DC_Comics)","https://upload.wikimedia.org/wikipedia/en/thumb/9/98/Steppenwolf_Earth_2_1.png/330px-Steppenwolf_Earth_2_1.png"],["Q2327890",210,"mechant","T-1000","C","Le T-1000 est un personnage de fiction créé par James Cameron et William Wisher Jr. dans le film Terminator 2: Le Jugement dernier en 1991.","Le T-1000 est un personnage de fiction créé par James Cameron et William Wisher Jr.","fr:T-1000",""],["Q2474195",214,"mechant","Ultron","E","Ultron est un super-vilain robotique évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Roy Thomas et le dessinateur John Buscema, le personnage de fiction apparaît pour la première fois dans le comic book Avengers #54 en juillet 1968.","Ultron est un super-vilain robotique évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Ultron","c:1/18/Dragon_Con_2013_-_Ultron_%289694672339%29.jpg"],["Q2296291",215,"mechant","Vautour","C","Adrian Toomes, alias le Vautour est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #2 en mai 1963.","Adrian Toomes, alias le Vautour est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Vautour_(comics)","c:b/b6/NYCC_2016_-_Daredevil%2C_Scorpion_%26_Vulture_%2830235176245%29.jpg"],["Q1358109",219,"film","Aladdin","C","Aladdin est un personnage de fiction qui est apparu pour la première fois en 1992 chez Disney, dans le long métrage d'animation Aladdin. Il est inspiré du personnage homonyme, héros du conte des Mille et Une Nuits, Aladin et la Lampe merveilleuse. Le personnage apparaît dans les suites du film sorties directement en vidéo: Le Retour de Jafar et Aladdin et le Roi des voleurs, ainsi que dans plusieurs séries télévisées, dont Aladdin, et des bandes dessinées.",115,"fr:Aladdin_(Disney)","c:b/b0/Jasmine%2C_Elizabeth_and_Aladdin.jpg"],["Q15614636",220,"film","Anna","C","Anna d'Arendelle est un personnage de fiction qui est apparu pour la première fois dans le 53e Classique d'animation des studios Disney, La Reine des neiges. Elle est interprétée en version originale par Kristen Bell, et doublée par Emmylou Homs en français, et par Véronique Claveau en français canadien.",116,"fr:Anna_(Disney)","c:7/7b/Anna_Frozen_meet-and-greets_at_Disneyland%2C_November_2013.jpg"],["Q2559332",223,"film","Cendrillon","C","Cendrillon est un personnage de fiction inspiré par le personnage du conte Cendrillon ou la Petite pantoufle de verre de Charles Perrault issu de Histoires ou Contes du Temps Passé. Walt Disney avait déjà adapté le conte dans un court-métrage d'animation Cinderella de 1922, produit avec son ancienne société de production Laugh-O-Gram. Disney décide de l'adapter en long métrage d'animation Cendrillon, sorti en 1950.",117,"fr:Cendrillon_(Disney)","c:1/14/Disney070817_070.jpg"],["Q857000",231,"film","Harold et les Dragons","C","Harold et les Dragons est une série de livres pour enfants de Cressida Cowell, chez les Vikings. Elle a été adaptée en films d'animation par DreamWorks avec Harold et son dragon Krokmou.","","en:How_to_Train_Your_Dragon_(novel_series)","https://upload.wikimedia.org/wikipedia/en/thumb/7/77/How_to_Train_Your_Dragon_%282003_book_cover%29.jpg/330px-How_to_Train_Your_Dragon_%282003_book_cover%29.jpg"],["Q73823",232,"film","Harry Callahan","C","Harold Francis « Dirty Harry » Callahan est un inspecteur fictif de la police de San Francisco dans les films de la saga L'Inspecteur Harry.",115,"fr:Harry_Callahan_(personnage)","c:9/92/Dirty_Harry_USA.jpg"],["Q2708262",235,"film","Jack Skellington","R","Jack Skellington est le personnage principal du film L'Étrange Noël de monsieur Jack, inspiré de Jack-o'-lantern, sous forme d'épouvantail. Inspiré également de Jack Pumpkinhead personnage de Return to Oz, en 1985.",118,"fr:Jack_Skellington","c:7/78/NYCC_2011_-_Jack_Skellington_%286253155660%29.jpg"],["Q2071301",242,"film","Katniss Everdeen","PC","Katniss Everdeen est un personnage de fiction, héroïne et narratrice de la trilogie Hunger Games écrite par Suzanne Collins. Elle est interprétée par Jennifer Lawrence dans son adaptation cinématographique.",115,"fr:Katniss_Everdeen","c:2/2c/Katniss_Everdeen%2C_Hunger_Games.jpg"],["Q748427",244,"film","L'Âne","C","L'Âne est un âne de fiction doué de la parole et l'un des personnages principaux de la série de films Shrek. Il a 30 ans possède une compagne, une dragonne et six enfants, mi-ânes mi-dragons, surnommés les dranons.","L'Âne est un âne de fiction doué de la parole et l'un des personnages principaux de la série de films Shrek.","fr:L'Âne_(Shrek)","c:2/25/Shrek_Esel_auf_dem_Eselsbrunnen_in_Halle_Saale_-_Alter_Markt_Stra%C3%9Fenkunst_-_panoramio.jpg"],["Q2283527",245,"film","Le Chat potté","C","Le Chat Potté, ou simplement Potté est un personnage d'animation apparaissant dans les films: Shrek 2, Shrek le troisième, Shrek 4: Il était une fin et deux spin-offs consacrés à son personnage, Le Chat potté, et Le Chat potté 2: La Dernière Quête.",111,"fr:Le_Chat_potté","c:f/f3/Chat_pott%C3%A9.jpg"],["Q3735317",250,"film","Mary Poppins","C","Mary Poppins est un personnage créé par l'écrivaine australienne Pamela L. Travers et popularisé par les studios Disney dans les films Mary Poppins avec Julie Andrews dans le rôle-titre, et Le Retour de Mary Poppins de Rob Marshall avec Emily Blunt dans le rôle de Mary Poppins. Elle est apparue pour la première fois dans le roman éponyme paru en 1934. Elle est reconnaissable grâce à son célèbre parapluie.","Mary Poppins est un personnage créé par l'écrivaine australienne Pamela L.","fr:Mary_Poppins_(personnage)","c:c/c8/MaryPoppins-perfect.jpg"],["Q2442950",251,"film","Max Rockatansky","C","Maximilian Rockatansky, dit Max Rockatansky, est un personnage de fiction créé par George Miller, Byron Kennedy et James McCausland, apparaissant pour la première fois dans le film Mad Max réalisé par George Miller. Il est interprété par Mel Gibson dans les trois premiers films de la saga sortis en 1979, 1981 et 1985, puis par Tom Hardy dans Mad Max: Fury Road.",114,"fr:Max_Rockatansky","c:8/80/Long_Beach_Comic_%26_Horror_Con_2011_-_Mad_Max_%286301702996%29.jpg"],["Q835154",252,"film","Michael Corleone","PC","Michael Corleone est un personnage de fiction dans les romans de Mario Puzo et dans la trilogie de films Le Parrain réalisée par Francis Ford Coppola avec la collaboration de cet auteur. Il est interprété au cinéma par Al Pacino. Michael est le plus jeune fils de Vito Corleone, parrain d'une des cinq familles mafieuses régnant sur le crime organisé aux États-Unis.",115,"fr:Michael_Corleone","c:5/56/Al_Pacino_-_Hummel.jpg"],["Q1750842",253,"film","Morpheus","C","Morpheus est un personnage fictif de la saga cinématographique Matrix, incarné dans les trois premiers épisodes de la saga par Laurence Fishburne.",117,"fr:Morpheus_(Matrix)","c:0/05/Laurence_Fishburne_2009_-_cropped.jpg"],["Q246838",254,"film","Mulan","C","Fa Mulan, ou simplement Mulan, est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Mulan, en 1998.",117,"fr:Mulan_(Disney)","c:a/ae/Disneyland_meet-and-greet_Mulan.jpg"],["Q3307548",258,"film","Po Ping","C","Po Ping est un personnage de fiction apparaissant dans l'univers de Kung Fu Panda, le film d'animation américain sorti en 2008. Il est le personnage principal des quatre films.",118,"fr:Po_Ping","c:f/f9/%E5%8C%97%E4%BA%AC%E7%8E%AF%E7%90%83%E5%BD%B1%E5%9F%8E%E5%8A%9F%E5%A4%AB%E7%86%8A%E7%8C%AB%E7%9B%96%E4%B8%96%E4%B9%8B%E5%9C%B0%E5%86%85%E7%9A%84%E9%98%BF%E5%AE%9D.jpg"],["Q4902053",260,"film","Raiponce","C","La princesse Raiponce est un personnage de fiction inspiré par le personnage du conte Raiponce des frères Grimm. Elle apparut pour la première fois dans le long métrage d'animation Raiponce, en 2010. Elle fait partie de la franchise Princesses Disney.","La princesse Raiponce est un personnage de fiction inspiré par le personnage du conte Raiponce des frères Grimm.","fr:Raiponce_(Disney)","c:4/42/Raiponce_-_20150803_16h45_%2810812%29.jpg"],["Q21772117",261,"film","Rey","PC","Rey est un personnage de fiction de l'univers Star Wars. Lors de sa première apparition, dans Star Wars, épisode VII: Le Réveil de la Force, où elle tient le rôle principal, elle est une jeune pilleuse d'épaves solitaire vivant sur la planète Jakku où elle a été abandonnée enfant. Rey attend le retour de ses parents, qu'elle ne connaît pas.","Rey est un personnage de fiction de l'univers Star Wars.","fr:Rey_(Star_Wars)","c:b/b7/Rey_Palpatine_at_Madame_Tussauds_London.jpg"],["Q496437",263,"film","Sarah Connor","C","Sarah Connor est un personnage de fiction créé par James Cameron pour son film Terminator sorti en 1984. Elle est aussi l'un des personnages centraux d'autres films de la franchise Terminator: Terminator 2: Le Jugement dernier, Terminator Genisys et Terminator: Dark Fate et de la série télévisée Terminator: Les Chroniques de Sarah Connor.","Sarah Connor est un personnage de fiction créé par James Cameron pour son film Terminator sorti en 1984.","fr:Sarah_Connor_(Terminator)","c:6/6c/Linda_Hamilton_by_Gage_Skidmore.jpg"],["Q52401",264,"film","Shrek","PC","Shrek est le personnage fictif et principal de la série de films Shrek, qui contient quatre longs métrages: Shrek, Shrek 2, Shrek le troisième et Shrek 4: Il était une fin et six courts métrages: Shrek 3D, Joyeux Noël Shrek !, Shrek, fais-moi peur !, Le Cochon qui criait au loup-garou, Le Noël Shrektaculaire de l'Âne et La Star de Fort Fort Lointain. Il est présenté comme un ogre vert, qui vit seul, isolé dans son marais, jusqu'à sa rencontre avec l'Âne.",114,"fr:Shrek_(personnage)","c:a/a4/Happy_Shrek.jpg"],["Q17510536",265,"film","Blanche-Neige (Disney)","C","Blanche-Neige est la princesse du conte des frères Grimm, héroïne du premier long métrage d'animation de Disney, Blanche-Neige et les Sept Nains (1937).","","en:Snow_White_(franchise)","c:0/0f/Snow_White_2025_film_logo.png"],["Q3498720",266,"film","Taxi Driver","C","Taxi Driver, ou Chauffeur de taxi au Québec, est un film américain réalisé par Martin Scorsese et sorti en 1976. Écrit par Paul Schrader, il met en vedette Robert De Niro, Jodie Foster, Harvey Keitel et Cybill Shepherd.","Taxi Driver, ou Chauffeur de taxi au Québec, est un film américain réalisé par Martin Scorsese et sorti en 1976.","fr:Travis_Bickle","https://upload.wikimedia.org/wikipedia/fr/thumb/3/30/Taxi_Driver.png/330px-Taxi_Driver.png"],["Q246835",267,"film","Trinity","E","Trinity est un des personnages principaux de la saga cinématographique Matrix.",null,"fr:Trinity_(Matrix)","c:4/45/Carrie-Anne_Moss_07_TIFF.jpg"],["Q21233695",268,"film","Vaiana","C","Vaiana de Motunui est le personnage principal du film d'animation Vaiana des studios Walt Disney, sorti en 2016.",null,"en:Moana_(character)","https://upload.wikimedia.org/wikipedia/en/thumb/5/56/Moana_%28character%29.png/330px-Moana_%28character%29.png"],["Q20749440",270,"film","WALL·E","C","WALL·E est le petit robot nettoyeur solitaire du film de Pixar (2008), resté seul sur une Terre recouverte de déchets, qui tombe amoureux de la robot EVE.","","en:WALL-E_(character)","https://upload.wikimedia.org/wikipedia/en/thumb/6/68/WALL-E_%28character%29.png/330px-WALL-E_%28character%29.png"],["Q738747",271,"film","Willy Wonka","R","Willy Wonka, est un personnage de fiction du roman Charlie et la Chocolaterie de Roald Dahl, de sa suite Charlie et le Grand Ascenseur de verre et de leurs adaptations cinématographiques.",118,"fr:Willy_Wonka","c:5/5b/Willy_Wonka_cosplay.jpg"],["Q209515",273,"litterature","Aladin ou la Lampe merveilleuse","PC","Aladin ou la Lampe merveilleuse, également intitulé Histoire d’Aladdin, ou la Lampe merveilleuse d'après son titre complet ou Aladin et la Lampe merveilleuse d'après une traduction erronée, voire simplement Aladin, est un conte traditionnel arabo-perse. Conte orphelin, il ne figure pas dans les manuscrits les plus anciens du recueil Les Mille et Une Nuits. Il y a été associé à partir du XVIIIe siècle avec la traduction française du recueil par Antoine Galland qui l'augmente de plusieurs contes.",114,"fr:Aladin_ou_la_Lampe_merveilleuse","c:3/38/Aladdin_in_the_Magic_Garden_-_Project_Gutenberg_eText_14221.jpg"],["Q58190302",275,"litterature","Ali Baba et les Quarante Voleurs","PC","Ali Baba et les Quarante Voleurs est un conte oriental mis par écrit pour la première fois par Antoine Galland en 1701, lorsqu'il a traduit en français Les Mille et Une Nuits, et incorporé dans ce recueil, alors qu'il n'a jamais été présent dans les manuscrits initiaux mais à leurs côtés oralement.",119,"fr:Ali_Baba_et_les_Quarante_Voleurs","c:c/ce/Robida_-_Alibaba_couverture.jpg"],["Q1269082",276,"litterature","Alice","C","Alice est un personnage de fiction britannique qui est le protagoniste du roman pour enfants de Lewis Carroll Les Aventures d'Alice au pays des merveilles et de sa suite De l'autre côté du miroir. Enfant, à l'ère victorienne, Alice se lance involontairement dans une aventure souterraine après être accidentellement tombée par un trou de lapin dans le pays des merveilles. Par la suite, elle traverse un miroir et entre dans un monde alternatif.",113,"fr:Alice_(Alice_au_pays_des_merveilles)","c:6/63/Alice_par_John_Tenniel_04.png"],["Q944201",277,"litterature","Alonso Quichano","C","Alonso Quijano, francisé Alonso Quichano, est le véritable nom de l'hidalgo Don Quichotte, personnage de fiction espagnol du roman Don Quichotte.",112,"fr:Alonso_Quichano","c:9/9b/202_112_quijote_cap44.jpg"],["Q461606",278,"litterature","Arsène Lupin","L","Arsène Lupin est un personnage de fiction français créé par Maurice Leblanc. Ce gentleman cambrioleur est particulièrement connu pour son talent consistant à user de déguisements, à se grimer et à prendre des identités multiples pour commettre ses délits et résoudre des énigmes criminelles.","Arsène Lupin est un personnage de fiction français créé par Maurice Leblanc.","fr:Arsène_Lupin","c:0/0a/Tourn%C3%A9e_de_l%27Ath%C3%A9n%C3%A9e_-_Ars%C3%A8ne_Lupin.jpg"],["Q525777",279,"litterature","Atticus Finch","C","Atticus Finch est l'avocat intègre du roman Ne tirez pas sur l'oiseau moqueur d'Harper Lee (1960), qui défend un homme noir injustement accusé dans l'Alabama des années 1930.","","en:Atticus_Finch","c:b/b7/Gregory_Peck_To_Kill_a_Mockingbird_still.jpg"],["Q751417",281,"litterature","Big Brother","PC","Big Brother, prononcé en français, est un personnage de fiction du roman 1984 de George Orwell. L'expression « Big Brother » est depuis utilisée pour qualifier toutes les institutions ou pratiques portant atteinte aux libertés fondamentales et à la vie privée des populations ou des individus.","Big Brother, prononcé en français, est un personnage de fiction du roman 1984 de George Orwell.","fr:Big_Brother","https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/1984_Social_Classes_alt.svg/330px-1984_Social_Classes_alt.svg.png"],["Q913841",283,"litterature","Bridget Jones","C","Bridget Jones est un personnage de fiction, créé par Helen Fielding. Elle apparaît en 1996 dans le roman Le Journal de Bridget Jones, puis dans ses suites, Bridget Jones: L'Âge de raison, Bridget Jones: Folle de lui et Bridget Jones Baby: Le Journal qui est un préquel du troisième livre.","Bridget Jones est un personnage de fiction, créé par Helen Fielding.","fr:Bridget_Jones","c:9/91/Miss_Potter_Premiere_%282%29.jpg"],["Q215894",284,"litterature","Candide","R","Candide ou l'Optimisme est un conte philosophique de Voltaire paru à Genève en janvier 1759. Il a été réédité vingt fois du vivant de l’auteur, ce qui en fait l'un des plus grands succès littéraires francophones. Seulement un mois après sa parution, six mille exemplaires avaient été vendus, nombre considérable pour l'époque.","Candide ou l'Optimisme est un conte philosophique de Voltaire paru à Genève en janvier 1759.","fr:Candide","c:4/4c/Candide1759.jpg"],["Q2630009",285,"litterature","Capitaine Achab","PC","Le capitaine Achab est un personnage de fiction, et le principal protagoniste du roman Moby Dick d’Herman Melville. C’est le capitaine monomaniaque du baleinier Pequod. Lors d’un précédent voyage, la baleine blanche Moby Dick a dévoré une jambe d’Achab, le laissant unijambiste, avec une prothèse faite d'ivoire. La chasse à la baleine du Pequod devient une chasse vengeresse contre Moby Dick, Achab incitant son équipage à le seconder dans sa mission fanatique.","Le capitaine Achab est un personnage de fiction, et le principal protagoniste du roman Moby Dick d’Herman Melville.","fr:Capitaine_Achab","c:8/8b/Moby_Dick_final_chase.jpg"],["Q1046049",286,"litterature","Capitaine Nemo","C","Le capitaine Nemo est un personnage de fiction créé par Jules Verne dans le roman Vingt Mille Lieues sous les mers. Il en est le personnage principal en tant que commandant du sous-marin Nautilus. Il est aussi l'un des personnages secondaires de L'Île mystérieuse et réapparaît sous les traits de Maître Volsius dans la pièce Voyage à travers l'impossible.","Le capitaine Nemo est un personnage de fiction créé par Jules Verne dans le roman Vingt Mille Lieues sous les mers.","fr:Capitaine_Nemo","c:9/9d/%27Twenty_Thousand_Leagues_Under_the_Sea%27_by_Neuville_and_Riou_027.jpg"],["Q864751",287,"litterature","Chapelier fou","C","Le Chapelier fou — ou Chapelier toqué selon certaines traductions — est un personnage de fiction qui apparaît pour la première fois lors d'un thé dans Les Aventures d'Alice au pays des merveilles de Lewis Carroll. Un personnage dessiné sous ses traits par John Tenniel apparaît sous le nom de « Hatta » dans la suite de l'histoire, De l'autre côté du miroir.",117,"fr:Chapelier_fou_(Alice_au_pays_des_merveilles)","c:0/01/%22Alice%27s_Adventures_in_Wonderland%22_by_Lewis_Carroll%2C_1907_book_cover_%28cropped%29.jpg"],["Q934013",288,"litterature","Chat du Cheshire","PC","Le chat du Cheshire est un chat tigré de fiction, qui apparaît dans le roman Les Aventures d'Alice au pays des merveilles de Lewis Carroll. Son nom est un hommage de Lewis Carroll au comté de Cheshire dans lequel il est né. Il est parfois appelé chat de Chester, d'après le nom de la capitale du comté. Il est souvent représenté avec un grand sourire.",110,"fr:Chat_du_Cheshire","c:a/ab/Tennel_Cheshire_proof.png"],["Q830561",289,"litterature","Commissaire Maigret","PC","Le commissaire Jules Maigret est un personnage de fiction, protagoniste et héros de 75 romans policiers et 28 nouvelles de Georges Simenon, publiés entre 1931 et 1972.",119,"fr:Commissaire_Maigret","c:1/12/SimenonMaigret-StudioHarcourt-1952.png"],["Q2453276",290,"litterature","Cosette","C","Cosette, surnom d'Euphrasie, est l'un des personnages du roman de Victor Hugo, Les Misérables.",null,"fr:Cosette","c:4/40/Cosette-sweeping-les-miserables-emile-bayard-1862.jpg"],["Q1048916",291,"litterature","Cyrano de Bergerac","R","Cyrano de Bergerac est l'une des pièces les plus populaires du théâtre français, et la plus célèbre de son auteur, Edmond Rostand. Librement inspirée de la vie et de l'œuvre de l'écrivain libertin Savinien de Cyrano de Bergerac, elle est représentée pour la première fois le 28 décembre 1897, au théâtre de la Porte-Saint-Martin, à Paris.",114,"fr:Cyrano_de_Bergerac_(Rostand)","c:a/a7/Coquelin_ain%C3%A9.jpg"],["Q744183",292,"litterature","D'Artagnan","C","Charles de Batz de Castelmore, dit d'Artagnan, est un mousquetaire français né entre 1611 et 1615 au château de Castelmore, près de Lupiac, en Gascogne et mort à Maastricht durant le siège de cette ville le 25 juin 1673, pendant la guerre de Hollande.",111,"fr:D'Artagnan","c:9/9a/D%E2%80%99Artagnan_-_1704.png"],["Q187349",293,"litterature","Docteur Watson","C","Le docteur Watson /ˈwat͡sən/ est un personnage de fiction créé par l'écrivain Arthur Conan Doyle. Watson est le meilleur ami du détective Sherlock Holmes et narrateur de presque toutes ses aventures, dans lesquelles il joue le plus souvent un rôle actif.","Le docteur Watson /ˈwat͡sən/ est un personnage de fiction créé par l'écrivain Arthur Conan Doyle.","fr:Docteur_Watson","c:7/77/Sherlock_Holmes_%26_Watson_-_The_Greek_Interpreter_-_Sidney_Paget.jpg"],["Q2583524",294,"litterature","Dorothy Gale","C","Dorothy Gale, aussi appelée Dorothée Gale en français, est un personnage de fiction de l'univers imaginaire d'Oz, inventé par l'auteur américain L. Frank Baum. Elle apparaît dès son premier roman, The Wonderful Wizard of Oz, et réapparaît dans nombre de ses suites. Elle est aussi le personnage principal de l'adaptation cinématographique, The Wizard of Oz, réalisée par Victor Fleming en 1939. Dans ce film, elle est incarnée par Judy Garland.",113,"fr:Dorothy_Gale","c:1/1a/Dorothy_Gale_with_silver_shoes.jpg"],["Q1952877",296,"litterature","Edmond Dantès","C","Edmond Dantès est un personnage de fiction français, héros du roman Le Comte de Monte-Cristo d'Alexandre Dumas.",null,"fr:Edmond_Dantès","c:6/61/%D0%94%D1%8E%D0%BC%D0%B0_%D0%93%D0%B0%D0%B2%D0%B0%D1%80%D0%BD%D0%B8_%D0%94%D0%B0%D0%BD%D1%82%D0%B5%D1%81_%D0%B2_1829.JPG"],["Q404121",298,"litterature","Edward Hyde","C","Edward Hyde, 1er comte de Clarendon, homme d'État et historien anglais;",null,"fr:Edward_Hyde",""],["Q6668",299,"litterature","Fifi Brindacier","R","Fifi Brindacier, de son nom complet Fifilolotte Victuaille Cataplasme Tampon Fille d'Efraïm Brindacier, est le personnage principal d'une série de romans pour enfants écrits à partir de 1945 par la romancière suédoise Astrid Lindgren.",110,"fr:Fifi_Brindacier","c:9/92/Pippi_Langkous_in_Nederland_1_%28crop%29.jpg"],["Q599351",300,"litterature","Gavroche","PC","Gavroche est un personnage du roman Les Misérables de Victor Hugo, qui prend les traits d'un enfant des rues parisien.",null,"fr:Gavroche","c:d/d5/Victor_hugo_gavroche_a_11_ans.jpg"],["Q2447542",301,"litterature","Hamlet","C","Hamlet est un protagoniste et le rôle-titre de la tragédie de William Shakespeare Hamlet. Il est Prince de Danemark, neveu de Claudius et fils du Roi Hamlet précédent roi de Danemark.","Hamlet est un protagoniste et le rôle-titre de la tragédie de William Shakespeare Hamlet.","fr:Hamlet_(personnage)","c:c/c2/Pedro_Am%C3%A9rico_-_Vis%C3%A3o_de_Hamlet.jpg"],["Q11829",302,"litterature","Hansel et Gretel","R","Hansel et Gretel, parfois intitulé Jeannot et Margot, est un conte populaire figurant parmi ceux recueillis par les frères Grimm dans le premier volume des Contes de l'enfance et du foyer.",115,"fr:Hansel_et_Gretel","c:d/d1/Hansel-and-gretel-rackham.jpg"],["Q170534",304,"litterature","Hercule Poirot","R","Hercule Poirot est un détective belge de fiction créé par la romancière anglaise Agatha Christie. Avec Miss Marple, c'est l'un des personnages les plus célèbres de la romancière, apparaissant dans 38 romans, 51 nouvelles, et deux pièces de théâtres, publiés depuis 1920. Depuis 2014, il continue ses aventures sous la plume de Sophie Hannah.","Hercule Poirot est un détective belge de fiction créé par la romancière anglaise Agatha Christie.","fr:Hercule_Poirot","c:b/b3/2011-07-26_Belgique_-_Ellezelles_-_Hercule_Poirot_002.jpg"],["Q720235",306,"litterature","Holden Caulfield","PC","Holden Caulfield est un personnage de fiction, créé par l'écrivain américain J. D. Salinger. Devenu populaire avec le roman L'Attrape-cœurs paru en 1951, il est considéré comme l'un des personnages les plus marquants de la littérature du XXe siècle.","Holden Caulfield est un personnage de fiction, créé par l'écrivain américain J.","fr:Holden_Caulfield","https://upload.wikimedia.org/wikipedia/en/thumb/5/5e/Holden_Caulfield.png/330px-Holden_Caulfield.png"],["Q2585477",307,"litterature","Javert","PC","Javert est l'un des personnages du roman Les Misérables de Victor Hugo. Cet inspecteur de police est l'ennemi juré de l’ex-forçat Jean Valjean en rupture de ban, qu'il pourchasse sans trêve. Il se suicide quand il comprend que Jean Valjean est un homme bon qui a tout fait pour se racheter, regrettant de l’avoir traqué.","Javert est l'un des personnages du roman Les Misérables de Victor Hugo.","fr:Javert","c:7/73/Javert.jpg"],["Q7048121",308,"litterature","Jay Gatsby","C","Jay Gatsby est le personnage de fiction éponyme de Gatsby le Magnifique, roman de Francis Scott Fitzgerald publié en 1925.",116,"fr:Jay_Gatsby","c:3/35/Warner_Baxter_as_Jay_Gatsby_in_The_Great_Gatsby_%281926%29_Retouched_Cropped.jpg"],["Q1156620",309,"litterature","Jean Valjean","R","Jean Valjean est l'un des principaux personnages du roman Les Misérables de Victor Hugo.",null,"fr:Jean_Valjean","c:f/fd/Monsieur_Madeleine_par_Gustave_Brion.jpg"],["Q1092632",310,"litterature","Juliette Capulet","C","Juliette Capulet est un des personnages titres de la tragédie Roméo et Juliette de William Shakespeare, l’autre protagoniste étant Roméo. Elle est la fille de 13 ans de Capulet, chef de la maison Capulet à Vérone. Le personnage a une longue histoire qui précède celle de Shakespeare.",111,"fr:Juliette_Capulet","c:7/73/John_William_Waterhouse_-_Juliet.jpg"],["Q161138",311,"litterature","La Barbe bleue","R","La Barbe bleue est un conte populaire communément dénommé Barbe bleue, dont la version la plus célèbre est celle de Charles Perrault, parue en 1697 dans Les Contes de ma mère l'Oye. C'est également le nom du personnage central du récit.",115,"fr:La_Barbe_bleue","c:9/96/Barbebleue1.jpg"],["Q661491",312,"litterature","La Esmeralda","C","La Esmeralda est l'un des principaux personnages du roman de Victor Hugo Notre-Dame de Paris, paru en 1831.",null,"fr:La_Esmeralda_(personnage)","c:f/fc/Merson_-_esmeralda-and-quasimodo-1905%281%29.jpg"],["Q11834",313,"litterature","Le Maître chat ou le Chat botté","PC","Le Maître chat ou le Chat botté est un conte franco-italien en prose racontant l'histoire d'un chat qui utilise la ruse et la tricherie pour offrir le pouvoir, la fortune et la main d'une princesse à son maître mal-né et sans-le-sou. L'auteur italien Giovanni Francesco Straparola semble avoir transcrit la plus ancienne version connue de cette histoire dans son livre Les Nuits facétieuses. La version classique de ce conte est écrite à la fin du XVIIe siècle par Charles Perrault.",119,"fr:Le_Maître_chat_ou_le_Chat_botté","c:2/24/Puss-in-Boots-1695.jpg"],["Q11838",314,"litterature","Le Petit Chaperon rouge","E","Le Petit Chaperon rouge est un conte de tradition orale d'origine française, classifié comme le conte-type 333 dans la classification Aarne-Thompson.",118,"fr:Le_Petit_Chaperon_rouge","c:9/97/Little_Red_Riding_Hood_by_Henry_Leverseege.jpg"],["Q1068229",315,"litterature","Lemuel Gulliver","C","Lemuel Gulliver est le héros et narrateur des Voyages de Gulliver de Jonathan Swift (1726), qui découvre le pays des minuscules Lilliputiens.","","en:Lemuel_Gulliver","c:4/43/Gullivers_travels.jpg"],["Q48479",316,"litterature","Les Aventures de Huckleberry Finn","C","Les Aventures de Huckleberry Finn est un roman picaresque de l'Américain Mark Twain, paru à Londres le 4 décembre 1884 sous le titre The Adventures of Huckleberry Finn, puis à New York en février de l'année suivante sous le titre Adventures of Huckleberry Finn.",118,"fr:Huckleberry_Finn","c:6/61/Huckleberry_Finn_book.JPG"],["Q1191282",317,"litterature","Lisbeth Salander","C","Lisbeth Salander est l’une des héroïnes de la série de romans policiers Millénium de l'écrivain suédois Stieg Larsson parue en Suède dès 2005. La série est ensuite prolongée par David Lagercrantz.",117,"fr:Lisbeth_Salander","https://upload.wikimedia.org/wikipedia/en/thumb/5/5a/Noomi_Rapace_as_Lisbeth_Salander.jpg/330px-Noomi_Rapace_as_Lisbeth_Salander.jpg"],["Q193531",318,"litterature","Miss Marple","PC","Jane Marple, plus connue sous le nom de Miss Marple, est un personnage de fiction créé par la romancière Agatha Christie et l'héroïne de douze romans policiers et de vingt-sept nouvelles.",111,"fr:Miss_Marple","c:8/8b/Dame_Agatha_Mary_Clarissa_Christie_%2812438790945%29.png"],["Q19399931",319,"litterature","Moby Dick","C","Moby Dick est le cachalot blanc géant du roman d'Herman Melville (1851), traqué avec obsession par le capitaine Achab.","","en:Moby_Dick_(whale)","c:7/7b/Moby_Dick_p510_illustration.jpg"],["Q3822980",320,"litterature","Méchante sorcière de l'Ouest","C","La méchante sorcière de l'Ouest est un personnage fictif créé par l'auteur américain L. Frank Baum comme le plus important antagoniste de son roman Le Magicien d'Oz publié en 1900. Dans les romans de Baum, elle n'a pas de nom; elle est seulement appelée « sorcière » ou « méchante sorcière ». Par la suite, elle reçut plusieurs dénominations:","La méchante sorcière de l'Ouest est un personnage fictif créé par l'auteur américain L.","fr:Méchante_sorcière_de_l'Ouest","c:8/83/Wickedwitchofwest.JPG"],["Q7087902",321,"litterature","Oliver Twist","C","Oliver Twist est l'orphelin héros du roman de Charles Dickens (1838), qui tombe dans une bande de jeunes pickpockets à Londres.","","en:Oliver_Twist_(character)","c:c/cd/George_Cruikshank_Oliver_Twist.gif"],["Q3899725",322,"litterature","Percy Jackson","PC","Persée « Percy » Jackson est un personnage de fiction de la série de romans fantasy Percy Jackson créée par Rick Riordan. Il est le héros et le narrateur de l'histoire, et également un des personnages principaux de la série Héros de l'Olympe. Il apparait aussi dans la série Les Travaux d'Apollon ainsi que dans Magnus Chase et les Dieux d'Asgard. Il est interprété par Logan Lerman dans les films et par Walker Scobell dans la série.",112,"fr:Percy_Jackson_(personnage)","c:4/4d/Walker_Scobell_by_Gage_Skidmore.jpg"],["Q1500073",323,"litterature","Pere Ubu","C","Pere Ubu est un groupe américain de rock parfois improprement présenté comme jouant du art rock avant-gardiste, originaire de Cleveland dans l'Ohio.",111,"fr:Pere_Ubu","c:e/e6/Pere_Ubu_Live_Vienna_2009.jpg"],["Q2587533",324,"litterature","Phileas Fogg","C","Phileas Fogg est le héros du Tour du monde en quatre-vingts jours, roman de Jules Verne paru en 1872.",null,"fr:Phileas_Fogg","c:0/05/%27Around_the_World_in_Eighty_Days%27_by_Neuville_and_Benett_04.jpg"],["Q6502703",325,"litterature","Pinocchio","R","Pinocchio est un personnage de fiction italien, héros du roman pour enfants Les Aventures de Pinocchio, écrit en 1881 par le journaliste et écrivain Carlo Collodi",117,"fr:Pinocchio","c:6/65/Pinocchio.jpg"],["Q1750634",326,"litterature","Quasimodo","PC","Quasimodo est le personnage principal du roman Notre-Dame de Paris de Victor Hugo, publié en 1831.",null,"fr:Quasimodo_(personnage)","c:1/14/Quasimodo_%28Livre_I%2C_Chapitre_V%29%2C_2019.3.1.jpg"],["Q673361",327,"litterature","Roméo Montaigu","C","Roméo Montaigu est l'un des deux personnages principaux de Roméo et Juliette, pièce de William Shakespeare écrite en 1594 - 1595.",116,"fr:Roméo_Montaigu","c:5/55/Romeo_and_juliet_brown.jpg"],["Q928202",329,"litterature","Rouletabille","C","Joseph Joséphin, surnommé Rouletabille, est un personnage récurrent de roman policier créé par Gaston Leroux dans son roman Le Mystère de la chambre jaune publié en 1907.",117,"fr:Rouletabille","c:4/4d/Le_Myst%C3%A8re_de_la_chambre_jaune_%28couverture%29.JPG"],["Q630823",331,"litterature","Sancho Panza","C","Sancho Panza, dont le nom est orthographié dans certaines langues Sancho Pança, est un personnage de roman. C'est l'écuyer et compagnon d'aventures d'Alonso Quichano dans le livre Don Quichotte de Miguel de Cervantes.","Sancho Panza, dont le nom est orthographié dans certaines langues Sancho Pança, est un personnage de roman.","fr:Sancho_Panza","c:5/55/Monumento_a_Cervantes_%28Madrid%29_10b.jpg"],["Q4653",333,"litterature","Sherlock Holmes","L","Sherlock Holmes est un personnage de fiction britannique créé par Sir Arthur Conan Doyle dans le roman policier Une étude en rouge en 1887.",115,"fr:Sherlock_Holmes","c:4/4a/Adventures_with_Sherlock_Holmes_TD_Gallery_Jan_5-Mar_10%2C_2012.jpg"],["Q122018",334,"litterature","Sinbad le marin","PC","Sinbad le marin, en persan Sindibad (aussi épelé « Sindbad » du persan: سندباد), est un conte surtout connu grâce au recueil Les Mille et Une Nuits, dans lequel il est généralement présent. Il narre les aventures de son personnage éponyme, un marin de la ville de Bagdad du temps de la dynastie des Abbassides. Durant ses voyages dans les mers de l'est de l'Afrique et du sud de l'Asie, Sinbad vit de nombreuses aventures fantastiques.",116,"fr:Sinbad_le_marin","c:9/90/Sinbad_1.jpg"],["Q170241",335,"litterature","Tarzan","PC","Tarzan est un personnage de fiction représentant l’enfant sauvage archétypal élevé par des Grands Singes dans la jungle africaine. Ce personnage est créé par Edgar Rice Burroughs en 1912 dans le roman Tarzan of the Apes, publié pour la première fois en France en 1926 chez Fayard, sous le titre Tarzan chez les singes. 26 volumes sont sortis entre 1912 et 1995.",119,"fr:Tarzan","c:6/61/Tarzan_of_the_Apes.jpg"],["Q6787521",336,"litterature","Matilda Wormwood","C","Matilda Wormwood est la petite fille surdouée du roman Matilda de Roald Dahl (1988), qui développe des pouvoirs de télékinésie face à des adultes odieux.","","en:Matilda_Wormwood","https://upload.wikimedia.org/wikipedia/en/thumb/3/39/Matilda-Mara-Wilson.webp/330px-Matilda-Mara-Wilson.webp"],["Q944203",337,"litterature","Tom Sawyer","C","Tom Sawyer est un personnage de fiction que Mark Twain a fait apparaître en 1876 dans Les Aventures de Tom Sawyer et dans plusieurs autres œuvres ultérieures. Inspiré de la jeunesse de l'auteur et du nom de son ami Tom Sawyer Spivey, c'est un personnage qui est devenu un symbole de liberté dans la culture populaire, mais que Twain a dépeint de manière contrastée et parfois critique.",116,"fr:Tom_Sawyer","c:1/1d/Tom_Sawyer_1876_frontispiece.jpg"],["Q626756",338,"litterature","Un chant de Noël","R","Un chant de Noël, également publié en français sous les titres Cantique de Noël, Chanson de Noël ou Conte de Noël, est le premier et le plus célèbre des contes écrits par Charles Dickens. Rédigé en même temps que Martin Chuzzlewit et paru en décembre 1843 chez Chapman & Hall avec des illustrations de John Leech, il est considéré comme « son œuvre la plus parfaite ». Aussitôt, Thackeray le salue comme un « bienfait national ». Salué par les critiques comme par le public, sa popularité n'a jamais faibli.",118,"fr:Ebenezer_Scrooge","c:9/99/Charles_Dickens-A_Christmas_Carol-Title_page-First_edition_1843.jpg"],["Q2320164",339,"litterature","Victor Frankenstein","PC","Victor Frankenstein est un personnage de fiction apparu pour la première fois dans le roman Frankenstein ou le Prométhée moderne de Mary Shelley en 1818. Il apparaît par la suite dans de nombreuses œuvres dérivées du roman.",110,"fr:Victor_Frankenstein","c:8/8d/The_Curse_Of_Frankenstein_%281957%29_trailer_-_Peter_Cushing_with_magnifying_glass.png"],["Q226822",340,"litterature","Zorro","R","Zorro — surnom qui signifie « renard » en espagnol — est un héros de fiction américain créé en 1919 par Johnston McCulley. Il apparaît pour la première fois dans le roman-feuilleton Le Fléau de Capistrano, aussi connu sous le titre Le signe de Zorro.",112,"fr:Zorro","c:a/a2/El_Zorro_y_su_parecido_en_primer_plano.jpg"],["Q53737957",341,"jeu","Aloy","C","Aloy est la protagoniste des jeux vidéo Horizon Zero Dawn sorti en 2017 et Horizon Forbidden West en 2022. Elle nait le 4 avril 3021 et est élevée par un paria du nom de Rost dans un monde post-apocalyptique luxuriant. Il l'entraîne afin qu'elle devienne une guerrière talentueuse, ce qui doit lui permettre de gagner l'Éclosion, une compétition rituelle organisée par la tribu des Noras, et de découvrir l'identité de sa mère.","Aloy est la protagoniste des jeux vidéo Horizon Zero Dawn sorti en 2017 et Horizon Forbidden West en 2022.","fr:Aloy","c:7/7a/Aloy_from_The_Frozen_Wilds_trailer.jpg",{"cats":["heros","persos_jv"]}],["Q935079",343,"jeu","Bob l'éponge","R","Bob l'éponge, communément appelé Bob, est un personnage de la série télévisée d'animation du même nom. Il apparaît pour la première fois dans l'épisode intitulé Bienvenue à bord ! diffusé aux États-Unis le 1er mai 1999. Il est doublé dans la version originale par Tom Kenny et par Sébastien Desjours en français. Bob l'éponge est conçu et réalisé par le biologiste et animateur Stephen Hillenburg peu après l'annulation à l'antenne de sa série Rocko's Modern Life en 1996.","Bob l'éponge, communément appelé Bob, est un personnage de la série télévisée d'animation du même nom.","fr:Bob_l'éponge_(personnage)","c:7/7a/SpongeBob_SquarePants_character.png"],["Q847571",344,"jeu","Bulbizarre et ses évolutions","E","Bulbizarre et ses évolutions, Herbizarre et Florizarre, sont trois espèces de Pokémon de la première génération.",null,"fr:Bulbizarre","c:6/64/Cosplay_of_Bulbasaur%2C_Anime_Expo_2010_%284837249076%29.jpg",{"cats":["heros","pokemon"]}],["Q845294",345,"jeu","Carapuce et ses évolutions","R","Carapuce et ses évolutions, Carabaffe et Tortank, sont trois espèces de Pokémon de la première génération.",null,"fr:Carapuce","c:f/fb/Bahnhof_Altbach_37.jpg",{"cats":["heros","pokemon"]}],["Q2722692",346,"jeu","Duke Nukem","C","Duke Nukem est un personnage de jeu vidéo, protagoniste d'une série de jeux d'action homonyme, créée par Todd Replogle, George Broussard, Allen Blum et Scott Miller, développeurs chez 3D Realms.",119,"fr:Duke_Nukem","c:4/45/Duke_Nukem_cosplay_at_WonderCon_2013_%288602096431%29.jpg"],["Q2250743",347,"jeu","Fantominus et ses évolutions","R","Fantominus et ses évolutions, Spectrum et Ectoplasma, sont trois espèces de Pokémon de la première génération.",null,"fr:Ectoplasma","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Pok%C3%A9mon_Gengar_art.png/330px-Pok%C3%A9mon_Gengar_art.png",{"cats":["heros","pokemon"]}],["Q2480066",348,"jeu","Goinfrex et Ronflex","R","Goinfrex et son évolution Ronflex sont deux espèces de Pokémon.",null,"fr:Ronflex","c:4/49/MAGFest_IMG_8541_%2832102985541%29.jpg",{"cats":["heros","pokemon"]}],["Q840368",349,"jeu","Jill Valentine","E","Jill Valentine est un personnage de la série vidéo-ludique Resident Evil, née en 1974.",null,"fr:Jill_Valentine","c:9/93/Julia_Voth_as_Jill_Valentine_crop.jpg",{"cats":["heros","horreur","persos_jv"]}],["Q904189",350,"jeu","Knuckles","PC","Knuckles the Echidna est un personnage de jeu vidéo de la série Sonic the Hedgehog. C'est un échidné rouge de 16 ans doté de dreadlocks. Knuckles est le gardien de l'île flottante d'Angel Island et de l'émeraude mère. Il possède des gants à pointes, ce qui lui permet de détruire certaines choses comme des piliers de pierre, mais aussi de grimper dans les murs. Il est ami et aussi rival de Sonic dans certains jeux.","Knuckles the Echidna est un personnage de jeu vidéo de la série Sonic the Hedgehog.","fr:Knuckles","c:c/c4/Knuckles_sculpture_in_Cin%C3%A9polis.png",{"cats":["heros","persos_jv"]}],["Q223684",351,"jeu","Lara Croft","E","Lara Croft est un personnage de fiction et la protagoniste de la série de jeux vidéo Tomb Raider et de sa série dérivée Lara Croft, dont la franchise appartient à Crystal Dynamics, et anciennement Eidos Interactive puis Square Enix. Lara Croft est présentée comme une archéologue belle, intelligente et athlétique, qui s'aventure de par le monde dans d'anciennes tombes ou ruines pleines de danger.",119,"fr:Lara_Croft","c:c/cd/Alison_Carroll_20080926_Festival_du_jeu_video_01.jpg",{"cats":["heros","jv","persos_jv"]}],["Q26183101",352,"jeu","Personnages de Peppa Pig","C","Les personnages de Peppa Pig, série d'animation britannique pour les tout-petits, réunissent Peppa, son petit frère George, Papa et Maman Pig et leurs amis animaux.","","en:List_of_Peppa_Pig_characters","c:8/84/PeppaPigAldridge2009.jpg"],["Q12379",353,"jeu","Mario","E","Mario est un personnage de jeu vidéo devenu la mascotte de Nintendo, facilement reconnaissable à sa moustache, à sa salopette bleue, à ses gants blancs et à sa casquette rouge marquée d'un M rouge inscrit dans un cercle blanc.",115,"fr:Mario_(personnage)","c:1/1f/JR-West_323_USJ_Super_Nintendo_World.jpg",{"cats":["heros","jv","persos_jv"]}],["Q2141803",354,"jeu","Mewtwo","E","Mewtwo est une espèce de Pokémon, créature de fiction appartenant à la franchise médiatique japonaise Pokémon. Sorte de « boss de fin » de la première génération de la franchise, il en est demeuré un symbole charismatique.","Mewtwo est une espèce de Pokémon, créature de fiction appartenant à la franchise médiatique japonaise Pokémon.","fr:Mewtwo","c:b/b4/Cosplay_of_Mewto_from_Pok%C3%A9mon_at_Anime_North_2013_%288860470787%29.jpg",{"cats":["heros","pokemon"]}],["Q9351",356,"jeu","Pikachu","M","Pikachu est une espèce de Pokémon, une créature de fiction issue de la franchise médiatique Pokémon de Nintendo. Il apparaît la première fois au Japon en 1996, dans les jeux vidéo Pokémon Bleu et Pokémon Rouge, créés par Satoshi Tajiri. Initialement conçu comme un personnage secondaire, Pikachu devient la mascotte de l'univers Pokémon après avoir été choisi comme personnage principal dans l'adaptation télévisuelle du jeu, aux côtés de son dresseur Sacha.","Pikachu est une espèce de Pokémon, une créature de fiction issue de la franchise médiatique Pokémon de Nintendo.","fr:Pikachu","c:a/a3/Cosplay_of_Pikachu%2C_Fanime_2015_%2818125488996%29.jpg",{"cats":["heros","jv","pokemon","persos_jv"]}],["Q72769780",357,"jeu","Sans","PC","Sans est un squelette farceur du jeu Undertale (2015), frère de Papyrus. Paresseux et blagueur en apparence, il cache un des combats les plus redoutables du jeu.","","en:Sans_(Undertale)","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/Undertale_Sans.png/330px-Undertale_Sans.png",{"cats":["heros","indie"]}],["Q120986062",358,"jeu","Ratchet et Clank","C","Ratchet et Clank sont le duo héros de la série de jeux vidéo d'Insomniac Games lancée en 2002 : un Lombax mécanicien et son petit robot intelligent.","","en:Ratchet_and_Clank_(characters)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c0/Ratchet_%26_Clank_%282021%29.png/330px-Ratchet_%26_Clank_%282021%29.png"],["Q1154303",359,"jeu","Riolu et Lucario","R","Riolu et son évolution Lucario sont deux espèces de Pokémon de quatrième génération.",null,"fr:Lucario","c:e/e1/Lucario_Cosplay.png",{"cats":["heros","pokemon"]}],["Q844940",360,"jeu","Salamèche et ses évolutions","R","Salamèche et ses évolutions, Reptincel et Dracaufeu, sont trois espèces de Pokémon de première génération.",null,"fr:Dracaufeu","c:5/58/Anime_Expo_2013_-_Charmander_Cosplay_%289228423198%29.jpg",{"cats":["heros","pokemon"]}],["Q3178753",361,"jeu","Dracaufeu","R","Salamèche et ses évolutions, Reptincel et Dracaufeu, sont trois espèces de Pokémon de première génération.",null,"fr:Salamèche","c:5/58/Anime_Expo_2013_-_Charmander_Cosplay_%289228423198%29.jpg",{"cats":["heros","pokemon"]}],["Q901323",362,"jeu","Scooby-Doo","PC","Scoobert-Doo, dit Scooby-Doo, est un personnage de fiction créé en 1969 par Iwao Takamoto, Joe Ruby et Ken Spears pour les studios Hanna-Barbera.",118,"fr:Scooby-Doo_(personnage)","c:5/51/Scooby_Doo_and_Daphne_Dancing.gif",{"cats":["heros","persos_anim"]}],["Q191626",364,"jeu","Sonic","E","Sonic, ou Sonic le Hérisson, est le personnage principal de la série de jeux vidéo Sonic the Hedgehog éditée par Sega. C'est un hérisson bleu qui a le pouvoir de courir à une vitesse supersonique et de se recroqueviller en une boule pour attaquer ses ennemis.","Sonic, ou Sonic le Hérisson, est le personnage principal de la série de jeux vidéo Sonic the Hedgehog éditée par Sega.","fr:Sonic","c:6/6e/Modern_Sonic.png",{"cats":["heros","jv","persos_jv"]}],["Q1753198",365,"jeu","Toudoudou et ses évolutions","R","Toudoudou et ses évolutions Rondoudou et Grodoudou sont trois espèces de Pokémon.",null,"fr:Rondoudou","c:0/00/View_of_Jigglypuff_street_art_on_Nile_Street_-_geograph.org.uk_-_6804560.jpg",{"cats":["heros","pokemon"]}],["Q15622224",366,"jeu","Trevor Philips","R","Trevor Philips est un personnage du jeu Grand Theft Auto V, figurant parmi les trois protagonistes du cinquième épisode de la série Grand Theft Auto.",119,"fr:Trevor_Philips","c:7/78/Steven_Ogg.png",{"cats":["heros","persos_jv"]}],["Q598503",367,"jeu","Vil Coyote","C","Vil Coyote est un personnage de dessin animé de la série Looney Tunes et Merrie Melodies, créé par Chuck Jones en septembre 1949. Le personnage apparaît pour la première fois dans le court-métrage Vite fait, mal fait aux côtés de son éternelle proie Bip-Bip.",113,"fr:Vil_Coyote","",{"cats":["heros","persos_anim"]}],["Q1263559",368,"jeu","Évoli et ses évolutions","R","Évoli et ses évolutions, Aquali, Voltali, Pyroli, Mentali, Noctali, Phyllali, Givrali et Nymphali, parfois désignés ensemble comme les évolitions, sont neuf espèces de Pokémon.",115,"fr:Évoli","c:7/7b/Pokemon_Eevee_Cosplayers_at_Animefest_2016.jpg",{"cats":["heros","pokemon"]}]]]);